!function(){"use strict";var a={noori:{1:{story:{title:"لیول 1: اندھیرا ٹاور — کمپیوٹر کے اندر",text:"اتوار کی شام نوری، مانو اور ہارمی امی ابو کے ساتھ لاؤنج میں بیٹھے تھے کہ اچانک گھر کا لیپ ٹاپ خود ہی جل اٹھا۔ اسکرین پر ایک ننھا سا نیلا روبوٹ ہاتھ ہلا رہا تھا۔<br><br>روبوٹ: السلام علیکم! میرا نام بائٹ ہے۔ میں ڈیجیٹل کنگڈم سے آیا ہوں۔<br>نوری: ڈیجیٹل کنگڈم؟ وہ کیا ہے؟<br>بائٹ: کمپیوٹرز کے اندر کی دنیا۔ وہاں بارہ روشن ٹاور ہیں۔ مگر <strong>گلچ</strong> نام کے ایک شرارتی بگ نے سب کی بتیاں بجھا دی ہیں!<br><br>بائٹ نے بتایا کہ پہلا ٹاور ایک ورکشاپ ہے، اور گلچ نے وہاں کمپیوٹر کے سارے حصے آپس میں ملا دیے ہیں۔<br>بائٹ: نوری، تم سب سے بڑی ہو۔ کیا میری مدد کرو گی؟ پہلے ہمیں سمجھنا ہے کہ کمپیوٹر کیسے کام کرتا ہے۔<br>نوری نے امی کی طرف دیکھا۔ امی مسکرائیں: جاؤ، ہم یہیں ہیں۔<br>نوری: چلو بائٹ، پہلا ٹاور روشن کرتے ہیں!"},finish:{title:"لیول 1 مکمل! 🎉 پہلا ٹاور روشن",text:"شاباش نوری! تم نے سمجھ لیا کہ کیبورڈ اور ماؤس <strong>Input</strong> دیتے ہیں، <strong>CPU</strong> کام کرتا ہے، اسکرین <strong>Output</strong> دکھاتی ہے اور ہارڈ ڈسک چیزیں سنبھال کر رکھتی ہے۔ ورکشاپ کا ٹاور پھر سے جگمگا اٹھا!<br>بائٹ: مگر دیکھو، پہاڑی پر ایک قلعہ ہے جس کے دروازے پر عجیب سے نمبر چمک رہے ہیں، صرف 0 اور 1۔ اگلی بار وہیں چلیں گے!"}},2:{story:{title:"لیول 2: سیکرٹ کوڈ کیسل",text:"اگلے دن نوری اسکول سے لوٹی تو کزن علی گھر آیا ہوا تھا۔ وہ بہت پریشان تھا۔<br>علی: میرا گیم اکاؤنٹ کسی اور نے کھول لیا! میرا پاس ورڈ تو بس 123456 تھا۔<br>اسی وقت لیپ ٹاپ پر بائٹ نظر آیا۔<br>بائٹ: نوری، ورکشاپ کا ٹاور روشن کرنے کا شکریہ! دوسرا ٹاور سیکرٹ کوڈ کیسل ہے۔ گلچ نے اس کا دروازہ <strong>بائنری</strong> کوڈ سے بند کر دیا ہے۔<br>نوری: بائنری کیا ہوتی ہے؟<br>بائٹ: کمپیوٹر کی زبان، جس میں صرف 0 اور 1 ہوتے ہیں۔ اور یاد رکھو، گلچ آسان پاس ورڈ بہت جلدی بوجھ لیتا ہے، بالکل علی کے پاس ورڈ کی طرح۔<br>نوری: علی، فکر نہ کرو۔ آج میں سیکھوں گی کہ مضبوط پاس ورڈ کیسے بنتا ہے، پھر تمہیں بھی سکھاؤں گی۔<br>بائٹ: تو چلو، قلعے کا دروازہ کھولتے ہیں!"},finish:{title:"لیول 2 مکمل! 🎉 کیسل روشن",text:"شاباش نوری! تم نے بائنری پڑھی اور قلعے کا دروازہ کھل گیا۔ تم نے یہ بھی سیکھا کہ لمبا اور مختلف لفظوں والا پاس ورڈ مضبوط ہوتا ہے، اور <strong>MFA</strong> اکاؤنٹ کو دوہری حفاظت دیتا ہے۔ پھر ابو کی مدد سے علی نے اپنا نیا مضبوط پاس ورڈ بنایا۔ دوسرا ٹاور جگمگا اٹھا!<br>مگر بائٹ کے پاس اچانک بہت سے عجیب پیغامات آنے لگے ہیں…"}},3:{story:{title:"لیول 3: مشکوک پیغامات",text:"شام کو امی کے فون پر ایک پیغام آیا: <em>مبارک ہو! آپ نے 50,000 روپے جیتے ہیں۔ فوراً اس لنک پر کلک کریں!</em><br>مانو خوشی سے اچھلی: امی، ہم امیر ہو گئے!<br>امی نے مسکرا کر فون ایک طرف رکھ دیا۔ نوری کو بھی کچھ گڑبڑ لگی۔<br>اسی وقت لیپ ٹاپ پر بائٹ آیا۔<br>بائٹ: نوری، کیسل کا ٹاور اب بھی روشن ہے، شاباش! مگر گلچ نے نئی شرارت شروع کی ہے۔ وہ پوری کنگڈم میں جعلی پیغامات بھیج رہا ہے۔ کچھ میں انعام کا لالچ ہے، کچھ میں جلدی کا دباؤ۔<br>نوری: بالکل امی کے فون والے پیغام کی طرح!<br>بائٹ: ہاں۔ اسے <strong>Phishing</strong> کہتے ہیں۔ تیسرا ٹاور روشن کرنے کے لیے ہمیں اصلی اور جعلی پیغام کا فرق سیکھنا ہے۔<br>نوری: ٹھیک ہے، آج میں ڈیٹیکٹیو نوری ہوں!"},finish:{title:"لیول 3 مکمل! 🎉 ڈیٹیکٹیو نوری",text:"شاباش! اب تم جعلی پیغام کی نشانیاں پہچانتی ہو: جلدی کا دباؤ، انعام کا لالچ، عجیب ای میل ایڈریس اور چھپا ہوا لنک۔ نوری نے مانو کو سمجھایا: انجان لنک پر کبھی کلک نہیں کرنا، پہلے کسی بڑے سے پوچھنا ہے۔ تیسرا ٹاور روشن ہو گیا!<br>مگر بائٹ پریشان ہے: نیٹ ورک سٹی میں پیغام راستے میں ہی گم ہو رہے ہیں۔"}},4:{story:{title:"لیول 4: نیٹ ورک سٹی",text:"ہفتے کی رات سب خالہ سے ویڈیو کال پر بات کر رہے تھے، مگر تصویر بار بار رک جاتی اور آواز ٹوٹ جاتی۔<br>ہارمی: خالہ کہاں چلی گئیں؟<br>ابو نے WiFi کا راؤٹر دیکھا: لگتا ہے ڈیٹا ٹھیک سے پہنچ نہیں رہا۔<br>تب لیپ ٹاپ پر بائٹ نظر آیا۔<br>بائٹ: نوری، تم نے پچھلی بار جعلی پیغام خوب پکڑے! چوتھا ٹاور نیٹ ورک سٹی میں ہے۔ گلچ نے وہاں راستوں کے نشان الٹ دیے ہیں، اس لیے ڈیٹا کے <strong>پیکٹ</strong> گم ہو رہے ہیں۔<br>نوری: پیکٹ کیا ہوتے ہیں؟<br>بائٹ: ڈیٹا کے چھوٹے ٹکڑے، جو ایک پتے کے ساتھ سفر کرتے ہیں، بالکل خط کی طرح۔ ہر ڈیوائس کا اپنا پتہ ہوتا ہے، اور راؤٹر انہیں راستہ دکھاتا ہے۔<br>نوری: تو چلو، پیکٹس کو صحیح گھر پہنچاتے ہیں!"},finish:{title:"لیول 4 مکمل! 🎉 نیٹ ورک سٹی روشن",text:"شاباش نوری! تم نے سیکھا کہ <strong>IP Address</strong> ہر ڈیوائس کا پتہ ہے، <strong>Router</strong> راستہ دکھاتا ہے اور <strong>DNS</strong> نام کو IP میں بدلتا ہے۔ گم شدہ پیکٹ گھر پہنچ گئے اور چوتھا ٹاور جگمگا اٹھا! ادھر ابو نے راؤٹر دوبارہ چلایا تو خالہ کی کال بھی صاف ہو گئی۔<br>بائٹ: اب لاجک لیب چلنا ہے، وہاں ایک روبوٹ بہت الجھا ہوا ہے۔"}},5:{story:{title:"لیول 5: لاجک لیب",text:"صبح امی نے کہا: نوری، آج چائے تم بناؤ گی۔ نوری نے پہلے کپ میں چینی ڈالی، پھر سوچ میں پڑ گئی: پانی پہلے ابالنا تھا یا پتی ڈالنی تھی؟<br>اتنے میں بائٹ کی آواز آئی: نوری، ترتیب بہت اہم ہوتی ہے!<br>بائٹ نے بتایا کہ پانچواں ٹاور لاجک لیب ہے۔ گلچ نے وہاں کے مددگار روبوٹ کی ہدایات الٹ پلٹ کر دی ہیں۔ اب روبوٹ ایک ہی جگہ گول گول گھوم رہا ہے۔<br>نوری: بیچارہ روبوٹ! جیسے ہم نے نیٹ ورک سٹی میں پیکٹس کو صحیح راستہ دکھایا تھا، ویسے ہی اسے صحیح ہدایات دیں گے۔<br>بائٹ: بالکل۔ قدم بہ قدم ہدایات کو <strong>Algorithm</strong> کہتے ہیں۔ آج ہم Loop اور if/else بھی سیکھیں گے۔<br>نوری: پہلے روبوٹ، پھر امی کی چائے!"},finish:{title:"لیول 5 مکمل! 🎉 لاجک لیب روشن",text:"Shabash Noori! Robot ab seedha chal raha hai, kyun ke aap ne usay sahi <strong>Algorithm</strong> diya, ek kaam bar bar karne ke liye <strong>Loop</strong> lagaya, aur <strong>if/else</strong> se faisla karna sikhaya. Paanchwan tower jagmaga utha, aur Ammi ki chai bhi bilkul sahi bani!<br>Byte: Ab tak hum ne hidayat sirf tarteeb mein lagayi hain. Agli baar hum ASLI Python code likhenge!"}},6:{story:{title:"لیول 6: کوڈ کریٹر",text:"Raat ko Noori ne dekha ke Abbu laptop par kuch likh rahe hain, aur screen par rang birange alfaaz chal rahe hain.<br>Noori: Abbu, yeh kya hai?<br>Abbu: Yeh code hai, beta. Mera daftar ka kaam isi se chalta hai.<br>Tabhi Byte screen ke kone se jhanka.<br>Byte: Noori! Logic Lab ka robot ab bilkul theek chal raha hai. Lekin chhatha tower, Code Crater, bilkul khamosh hai. Glitch ne wahan ke saare messages mita diye hain. Ab yeh tower sirf usi ki baat sunega jo khud code likh sake.<br>Noori: Main? Asli code?<br>Byte: Haan! Aaj hum <strong>Python</strong> mein likhenge: screen par salam, ek variable, aur ek chhota sa loop. Error aaye to ghabrana nahi, parh kar theek karna.<br>Abbu muskuraye: Main bhi saath baithta hoon.<br>Noori: Tayyar hoon!"},finish:{title:"لیول 6 مکمل! 🎉",text:"Byte: Yeh raha asli programmer banne ka pehla qadam! Noori ki pehli print line chalte hi Code Crater mein roshni phail gayi: <strong>Salam, Duniya!</strong> Aap ne variable bhi banaya aur loop bhi chalaya. Abbu ne zor se taali bajayi. Chhatha tower roshan!<br>Lekin agle din Noori ne school ki website kholi, to aadha page toota hua tha…"}},7:{story:{title:"لیول 7: ویب گارڈینز",text:"Noori school ki website par apna result dekhna chahti thi. Lekin page ajeeb tha: rang ghayab, buttons band, aur ek link par likha tha <strong>404</strong>.<br>Noori: Is website ko kya hua?<br>Byte laptop par aaya.<br>Byte: Code Crater ab roshan hai, shabash! Magar saatwan tower Web Guardians ka hai, aur Glitch ne wahan ki website ke teen hisse bikher diye hain.<br>Noori: Kaun se teen hisse?<br>Byte: <strong>HTML</strong> jo dhancha banata hai, <strong>CSS</strong> jo rang aur style deta hai, aur <strong>JavaScript</strong> jo buttons ko zinda karta hai.<br>Noori: Jaise ghar ki deewarein, rang-rogan, aur bijli ke switch!<br>Byte: Bilkul! Chalo website ko phir se jodte hain."},finish:{title:"لیول 7 مکمل! 🎉",text:"Shabash! Aap ne HTML, CSS aur JavaScript ka kaam samajh liya, aur yeh bhi ke <strong>404</strong> ka matlab hai page nahi mila. Website phir se sundar ho gayi aur saatwan tower jagmaga utha! Noori ne apna result bhi dekh liya.<br>Lekin Byte ne ek aur baat note ki: Glitch website mein kisi chhupe raste se ghusa tha. Agli baar woh kamzori dhoondni hai."}},8:{story:{title:"لیول 8: ویلنریبلٹی والٹ",text:"رات کو نوری نے دیکھا کہ گھر کا بڑا دروازہ تو بند ہے، مگر پیچھے صحن کی کھڑکی کھلی رہ گئی ہے۔<br>نوری: امی، اس کھڑکی سے تو بلی بھی اندر آ سکتی ہے!<br>امی نے ہنس کر کھڑکی بند کر دی۔<br>اگلے دن بائٹ آیا۔<br>بائٹ: نوری، پچھلی بار تم نے ویب سائٹ جوڑ دی تھی۔ مگر پتا چلا ہے کہ گلچ ایک چھپے راستے سے اندر آیا تھا۔ آٹھواں ٹاور ویلنریبلٹی والٹ ہے۔ یہ پریکٹس والا والٹ ہے، جہاں ہم محفوظ طریقے سے کمزوریاں ڈھونڈنا سیکھتے ہیں۔<br>نوری: کمزوری یعنی کھلی کھڑکی؟<br>بائٹ: بالکل! <strong>Vulnerability</strong> ایسی کمزوری ہے جو نقصان کا راستہ بنے۔ ہم اسے ڈھونڈیں گے، ٹھیک کریں گے، اور پھر دوبارہ چیک بھی کریں گے۔<br>نوری: تو چلو، ساری کھڑکیاں بند کرتے ہیں!"},finish:{title:"لیول 8 مکمل! 🎉",text:"Shabash Noori! Aap ne kamzoriyan pehchanna seekh liya, jaise Broken Access Control aur Injection. Aur un ka hal bhi: <strong>Least Privilege</strong>, validation, patch, aur phir retest. Chhupa rasta band hua aur aathwan tower roshan ho gaya!<br>Magar raat 3 baje Byte ke paas ek ajeeb alarm bajne laga…"}},9:{story:{title:"لیول 9: Cyber Defence Centre",text:"Subah naashte par laptop ki screen par ek laal batti jal rahi thi.<br>Byte: Noori! Raat 3 baje kuch ajeeb hua. Vault ka chhupa rasta to band hai, magar Glitch ne nawen tower ke darwaze par baar baar ghalat password try kiye hain.<br>Noori: Kitni baar?<br>Byte: Yahi to pata karna hai! Har koshish ka record <strong>logs</strong> mein likha hota hai: kisne, kab, aur kya kiya.<br>Mano: Jaise Ammi ki diary mein har kharcha likha hota hai?<br>Byte: Bilkul, Mano! Aaj Noori ek <strong>SOC Analyst</strong> banegi. Hum FAILED logins filter karenge, aur dekhenge ke kaunsa IP baar baar fail ho raha hai.<br>Noori ne chai ka cup side par rakha aur screen ke qareeb ho gayi.<br>Noori: Chalo Byte, investigation shuru karte hain!"},finish:{title:"لیول 9 مکمل! 🎉",text:"Shabash! Aap ne logs filter kiye, baar baar fail hone wala IP pakra, aur samjha ke bohat saare failed logins ke baad ek success <strong>Brute Force</strong> ki nishani hai. Aap ab ek real SOC analyst ki tarah soch sakti hain! Defence Centre ka nawan tower roshan ho gaya.<br>Byte: Lekin Glitch jaate jaate kuch files chhed gaya hai. Ab saboot se sach tak pohanchna hai."}},10:{story:{title:"لیول 10: ڈیجیٹل فارنزکس",text:"Ghar mein shor macha hua tha: Ammi ka banaya hua cake fridge se aadha ghayab tha! Sab ne Mano ki taraf dekha.<br>Noori: Ruko! Pehle saboot dekhte hain. Plate par chocolate ke nishan hain, aur kitchen ki light raat 11 baje jali thi.<br>Aakhir pata chala ke Abbu ne raat ko khaya tha! Sab hans pade.<br>Byte: Wah Noori, tum ne andaza nahi lagaya, saboot dekha. Yahi <strong>Forensics</strong> hai!<br>Byte ne bataya ke Glitch ne Defence Centre se ghus kar daswein tower ki files chhedi thin. Ab sach dhoondna hai.<br>Byte: Yaad rakhna, original file ko kabhi nahi chhedte, copy par kaam karte hain. <strong>Timestamp</strong> batata hai kab hua, aur <strong>Hash</strong> file ki pehchan hai.<br>Noori: Chalo, saboot jama karte hain!"},finish:{title:"لیول 10 مکمل! 🎉",text:"Shabash, Detective Noori! Aap ne copy par kaam kiya, timestamp aur hash dekhe, <strong>Chain of Custody</strong> ka record rakha aur sab baton ki <strong>Timeline</strong> banayi. Sach saboot se mila, andaze se nahi. Daswan tower roshan!<br>Byte: Ab gyarahwan tower AI World hai. Wahan ek robot guard hai jise Glitch baaton mein phansana chahta hai…"}},11:{story:{title:"لیول 11: AI Mystery World",text:"Mano ne phone par ek AI app se poocha: Kya bandar ud sakte hain? AI ne bari sanjeedgi se kaha: Haan! Noori hans padi: Yeh to ghalat hai!<br>Byte: Isi liye aaj ka sabaq zaroori hai. Pichli baar tum ne saboot se sach dhoonda tha. Aaj AI ke ASLI secrets seekhenge.<br>Byte ne bataya ke gyarahwan tower <strong>GuardBot</strong> naam ka AI sambhalta hai, aur Glitch usay baaton mein phansa kar secret nikalna chahta hai.<br>Noori: AI ko baaton se kaise bewaqoof banate hain?<br>Byte: Isay <strong>Prompt Injection</strong> kehte hain. Aur agar AI ko ghalat data se sikhaya jaye to woh <strong>Data Poisoning</strong> hai. Hum practice mein dono khud try karenge, taake samajh sakein. Phir defender ban kar AI ko helper ki tarah use karenge.<br>Noori: Matlab AI ki har baat check karni hai!"},finish:{title:"لیول 11 مکمل! 🎉",text:"Byte: Noori! Ab aap AI ko samajhti hain, dushman ke taur par nahi, TOOL ke taur par! Aap ne dekha ke AI ko trick bhi kiya ja sakta hai aur ghalat data se bigaara bhi ja sakta hai, is liye har jawab VERIFY karna hai. GuardBot ne secret sambhal liya aur gyarahwan tower roshan ho gaya.<br>Ab sirf aakhri tower baqi hai, aur Glitch wahin chhupa hai!"}},12:{story:{title:"لیول 12: Cyber HQ Case File",text:"Gyarah tower roshan ho chuke the. Poori Digital Kingdom jagmaga rahi thi, siwaye aakhri tower ke: Cyber HQ.<br>Byte: Noori, AI World mein tum ne kamaal kiya! Magar ab ek emergency hai. Kingdom ki ek company, <strong>Acme Corp</strong> (yeh farzi company hai), ka server aaj raat 10 baje band ho gaya, aur database se data ghayab hai. Saare ishare Glitch ki taraf hain.<br>Mano aur Harmi bhi laptop ke paas aa baithe.<br>Mano: Aapi, aap pakar logi na?<br>Noori ne gehri saans li. Network, web logs, passwords, saboot: jo kuch seekha tha, sab yaad aa raha tha.<br>Noori: Ab tak jo seekha, sab kaam aayega. Main ek asli Cyber Detective ki tarah investigation karungi!<br>Byte: To case file kholo!"},finish:{title:"🏆 DIGITAL KINGDOM HERO!",text:"Byte: Noori! Aap ne Level 12 bhi mukammal kar liya! Saboot jode, timeline banayi, report likhi, aur Glitch pakra gaya. Glitch ne sharminda ho kar kaha: Sorry, main sirf shararat kar raha tha. Ab main achha bug banunga! Aakhri tower roshan hua aur poori Digital Kingdom jagmaga uthi. 12 levels, 12 skills, ek amazing journey. Mubarak ho!<br>Lekin Byte ke haath mein ek sunehri chabi hai…"}},13:{story:{title:"Master Academy Mein Khush Aamdeed",text:"Digital Kingdom ke saare tower roshan the, aur Glitch ab Byte ka chhota sa helper ban gaya tha. Ek din Byte ek sunehri chabi le kar aaya.<br>Byte: Noori, tum ne 12 levels mukammal kar liye! Yeh Master Academy ki chabi hai. Ab tum sirf bachana nahi, banana bhi seekhogi.<br>Usi shaam Noori ka school project bigar gaya: ghalti se purani file naye kaam ke upar save ho gayi! Do din ki mehnat ghayab.<br>Noori: Kaash main pichla version wapis la sakti!<br>Byte: La sakti ho, agar <strong>Git</strong> use karo. Git tumhare code ki history save karta hai. Aur <strong>GitHub</strong> par duniya bhar ke engineers apna code rakhte aur mil kar kaam karte hain.<br>Glitch: Main ne bhi kai baar files bigaari hain. Mujhe bhi seekhna hai!<br>Noori: To chalo, asli engineers ki tarah code save karte hain!"},finish:{title:"🌟 Level 13 Complete!",text:"Shabash Noori! Aap ne apna pehla Master Level complete kar liya. Ab aap asli developer ki tarah code save kar sakti hain: har badlaav Git ki history mein mehfooz, aur GitHub par saath kaam karne ke liye tayyar. Is baar school project ka har version mehfooz hai!<br>Byte: Agli baar hum ek nayi duniya mein jayenge, jahan mouse se zyada kaam ek kaali screen par commands se hota hai…"}},14:{story:{title:"Ethical Hacker Ka Playground",text:"Pichli baar Noori ne Git se apna code mehfooz karna seekha tha. Aaj Byte laptop par ek kaali screen khol kar baitha tha.<br>Noori: Yahan mouse kahan hai?<br>Byte: Yeh <strong>Terminal</strong> hai. Yahan hum commands likh kar kaam karte hain. Aur yeh <strong>Kali Linux</strong> hai, security seekhne walon ka mashhoor Operating System.<br>Mano ne jhank kar poocha: Aapi, kya aap hacker ban jaogi?<br>Noori: Hacker nahi, <strong>Ethical Hacker</strong>! White Hat.<br>Byte: Bilkul. Ethical Hacker sirf ijazat le kar system check karta hai, taake kamzori malik ko bata kar theek karwayi ja sake. Bina ijazat kisi ka network scan karna ghalat hai.<br>Glitch: Achha hua main sudhar gaya!<br>Noori: To chalo, pehli commands seekhte hain."},finish:{title:"🌟 Level 14 Complete!",text:"Zabardast! Aap ne Kali Linux aur Terminal ke basics seekh liye: <strong>ls</strong> se files dekhna, <strong>cd</strong> se folder badalna, aur yeh ke <strong>nmap</strong> jaisa scan sirf ijazat ke saath karna hai. Aap ki soch ab White Hat hai: logon ko bachana.<br>Byte: Ab chalo future ki taraf. Agli baar dekhenge ke AI aur apps aapas mein kaise baat karte hain!"}},15:{story:{title:"Aane Wala Daur",text:"Kali Linux ke baad Noori ko lagta tha ke woh computer ki zabaan samajhne lagi hai. Usi shaam sab restaurant gaye. Waiter ne Abbu ka order liya, kitchen mein gaya, aur garam garam biryani le aaya.<br>Byte (Noori ke phone se): Dekha? Yeh waiter bilkul ek <strong>API</strong> jaisa hai!<br>Noori: Woh kaise?<br>Byte: Aap ki app restaurant hai. App API se kehti hai: mujhe data chahiye. API server ki kitchen se data la kar deti hai. Isi tarah weather app tak mausam ka haal pohanchta hai.<br>Noori: Aur AI se behtareen jawab kaise lete hain?<br>Byte: Yahi aaj ka doosra sabaq hai. Aane wale daur mein har jagah AI hoga, is liye isay sahi use karna aana chahiye.<br>Noori ne biryani ka luqma liya: Theek hai, ghar ja kar shuru!"},finish:{title:"🌟 Level 15 Complete!",text:"Zabardast! Aap ne API aur AI ki duniya samajh li. Ab aap jaanti hain ke app API ke zariye server se data mangwati hai, bilkul waiter aur kitchen ki tarah, aur AI se achha jawab kaise liya jata hai.<br>Byte: Noori, ab tumhare paas bohat saari skills hain. Aakhri Master Level mein dekhenge ke in skills se kisi ki madad kaise ki jaye, aur shayad pehli kamai bhi!"}},16:{story:{title:"Skill Ko Paisa Banayein",text:"API ke baad Noori ke paas skills ka poora bag tha. Ek din Khala ka phone aaya: Noori, main ghar se cupcakes bechti hoon. Kya tum meri bakery ke liye ek chhoti si website bana sakti ho?<br>Noori ki aankhein chamak uthin. Us ne Abbu se poocha, aur Abbu ne kaha: Zaroor, main saath rahunga.<br>Byte: Yeh tumhara pehla asli client hai! Pehle ek <strong>Portfolio</strong> banao, yaani apni website jahan tumhare games aur projects nazar aayen. Internet par log apne kaam ke liye log dhoondte hain, isay <strong>Freelancing</strong> kehte hain. Aur yaad rakhna, online kaam hamesha bade ki ijazat aur nigrani mein.<br>Glitch: Aur agar kaam mushkil lage to?<br>Byte: Achha sawal! Is ka jawab bhi aaj seekhenge.<br>Noori: Chalo, pehli deal karte hain!"},finish:{title:"🌟 Level 16 Complete!",text:"Mubarak ho! Ab aap ek Professional Junior Engineer hain. Khala ki bakery ki website ban gayi, aur Khala ne Noori ko cupcakes ka pehla dabba tohfe mein diya. Byte aur Glitch ne mil kar taaliyan bajayin. Ek andhere Digital Kingdom se apni pehli website tak, kya safar tha!<br>Ab Noori ki baari hai: woh Mano aur Harmi ko sikhayegi. Aur agla hero… aap!"}}},mano:{1:{story:{title:"لیول 1: کمپیوٹر کے حصے",text:"صبح مانو نے دیکھا کہ گھر کے ٹیبلٹ پر ایک ننھا سا روبوٹ اداس بیٹھا ہے۔<br>مانو: تم کون ہو؟ اداس کیوں ہو؟<br>روبوٹ: میں بائٹ ہوں! میری <strong>ہیرو شیلڈ</strong> پر بارہ چمکتے ستارے تھے۔ گلچ نام کا ایک شرارتی بگ انہیں چھپا کر بھاگ گیا!<br>مانو: میں ڈھونڈوں گی!<br>بائٹ: شاباش! پہلا ستارہ کمپیوٹر کے اندر چھپا ہے۔ اسے ڈھونڈنے کے لیے کمپیوٹر کے حصے پہچاننے ہوں گے: کیبورڈ، ماؤس، اسکرین اور CPU۔<br>مانو نے ٹیبلٹ مضبوطی سے پکڑا: چلو بائٹ، آؤ دیکھیں!"},finish:{title:"🌟 لیول 1 مکمل!",text:"Byte: Shabash Mano! Aap computer ke hisse jaanti hain! Keyboard se hum likhte hain, CPU sochta hai, aur screen dikhati hai. Aur dekho, CPU ke peeche se pehla chamakta sitara nikal aaya! Shield par ek star jagmagaya.<br>Byte: Agla sitara ek tale wale sandooq mein tha. Us ki chabi ek password hai!"}},2:{story:{title:"لیول 2: پاس ورڈ کا راز",text:"Pehla sitara mil gaya tha! Aaj Byte ne Mano ko ek khaali sandooq dikhaya.<br>Byte: Mera doosra sitara is mein tha. Is ka password sirf 1234 tha, is liye Glitch ne foran khol liya!<br>Mano: Itna aasan password?<br>Byte: Haan. <strong>Password</strong> ek secret chabi hai jo aap ka account mehfooz rakhti hai. Kamzor chabi, aasan chori.<br>Mano: Phir mazboot password kaisa hota hai?<br>Byte: Lamba, ajeeb, aur har account ka alag. Aur password sirf Ammi Abbu ko pata ho, dost ko bhi nahi.<br>Mano: Chalo, sitara wapis laate hain!"},finish:{title:"🔐 لیول 2 مکمل!",text:"Byte: Shabash! Aap passwords ki expert hain! Mano ne sandooq ko lamba aur mazboot password diya, aur <strong>MFA</strong> bhi lagaya: password ke saath phone par ek code. Ab Glitch ki ek na chali! Doosra sitara wapis shield par chamak utha.<br>Lekin tablet par ek ajeeb message aa gaya hai…"}},3:{story:{title:"لیول 3: محفوظ پیغام",text:"Do sitare wapis aa gaye the! Aaj tablet par ek message aaya: <em>Tum ne inaam jeeta hai! Teesra sitara lene ke liye foran is link par click karo!</em><br>Mano ki ungli link ki taraf barhi.<br>Byte: Ruko Mano! Yeh message kis ne bheja?<br>Mano: Pata nahi… koi anjaan hai.<br>Byte: Yeh Glitch ki chaal ho sakti hai. Isay <strong>phishing</strong> kehte hain, yaani dhoka. Kuch messages safe hote hain, kuch dhokay wale.<br>Mano: To main kaise pehchanoon?<br>Byte: Aaj nishaniyan seekhte hain. Aur shak ho to pehle Ammi ya Abbu ko dikhao!"},finish:{title:"🛡️ لیول 3 مکمل!",text:"Byte: Shabash Mano! Aap Safety Detective hain! Aap ne pehchaan liya ke foran click karo aur inaam jeeta jaise message dhoka ho sakte hain. Mano ne link nahi dabaya, Ammi ko dikhaya. Is samajhdari par teesra sitara khud chamak kar saamne aa gaya!<br>Byte: Agla sitara computers ke beech safar kar raha hai. Chalo network mein chalte hain!"}},4:{story:{title:"لیول 4: نیٹ ورک",text:"Teen sitare wapis aa chuke the! Aaj Mano ne Noori Aapi ke liye ek chitthi likhi, aur upar Aapi ke kamre ka naam likha, taake sahi jagah pohanche.<br>Byte: Wah! Computers bhi aise hi baat karte hain, jaise dost chitthiyan bhejte hain.<br>Mano: Sach mein?<br>Byte: Haan! Har computer ka ghar ka pata hota hai: <strong>IP Address</strong>. Data chhote <strong>packet</strong> ban kar safar karta hai. Aur <strong>router</strong> traffic police ki tarah raasta dikhata hai.<br>Mano: Aur chautha sitara?<br>Byte: Glitch ne usay ek packet mein chhupa kar ghalat raste par bhej diya hai! Chalo sahi raasta dhoondte hain."},finish:{title:"🌐 لیول 4 مکمل!",text:"Byte: Shabash! Network ka expert! Mano ne packet ko sahi pata diya, router ne raasta dikhaya, aur chautha sitara seedha Byte ke paas pohanch gaya. Mano ki chitthi bhi Aapi tak pohanch gayi!<br>Byte: Agla sitara ek ajeeb tarteeb ke peeche chhupa hai: laal, neela, laal, neela… agla kya hoga?"}},5:{story:{title:"لیول 5: ترتیب اور پیٹرن",text:"Chaar sitare mil gaye! Aaj Ammi ne Mano ko mehndi ka ek design dikhaya: phool, patta, phool, patta.<br>Ammi: Batao, agla kya aayega?<br>Mano: Phool!<br>Byte: Wah Mano! Isay <strong>pattern</strong> kehte hain, yaani tarteeb. Computers bhi patterns se kaam karte hain.<br>Byte ne bataya ke Glitch ne paanchwan sitara ek lambi tarteeb ke peeche chhupa diya hai. Darwaza tabhi khulega jab koi bataye ke aage kya aayega.<br>Mano: Main pattern dhoondne mein maahir hoon! Chalo!"},finish:{title:"🧩 لیول 5 مکمل!",text:"Byte: Shabash! Aap patterns ki jaadugar hain! Mano ne sahi bataya ke agla kya aayega, aur dots jod kar ek star bhi banaya. Darwaza khula aur paanchwan sitara chamak utha!<br>Byte: Ab Glitch ne chhatha sitara ek khilona robot ko de diya hai, jo hamari baat hi nahi samajhta. Usay hidayat deni hongi!"}},6:{story:{title:"لیول 6: کوڈنگ کی بنیاد",text:"Paanch sitare wapis! Aaj ek chhota khilona robot chhatha sitara pakre khara tha, magar hil hi nahi raha tha.<br>Mano: Robot, chalo!<br>Robot chup.<br>Byte: Robot ko hidayat chahiye, sahi tarteeb mein. Isay <strong>code</strong> kehte hain, jaise robot ko aage chalo kehna.<br>Mano: Jaise Ammi chai banane ke steps batati hain?<br>Byte: Bilkul! Kaam ki tarteeb <strong>sequence</strong> hai. Ek kaam bar bar karna <strong>loop</strong> hai. Aur agar aisa ho to yeh karo, yeh <strong>condition</strong> hai.<br>Mano: Robot, tayyar ho jao!"},finish:{title:"🐍 لیول 6 مکمل!",text:"Byte: Shabash! Aap programmer ban rahi hain! Mano ke code se robot aage chala, phir loop se 10 baar shabash bola, aur khushi se chhatha sitara Byte ko de diya.<br>Byte: Agla sitara ek website mein chhupa hai, magar Glitch ne us ke rang aur buttons ghayab kar diye hain!"}},7:{story:{title:"لیول 7: ویب سائٹ",text:"Chhe sitare chamak rahe the! Aaj Mano apni pasandeeda cartoon website kholna chahti thi, magar wahan sirf kaale alfaaz the. Na rang, na button!<br>Mano: Is website ko kya hua?<br>Byte: Glitch ki shararat! Website 3 cheezon se banti hai, aur us ne teeno bikher di hain.<br>Mano: Kaun si teen?<br>Byte: <strong>HTML</strong> dhancha banata hai, jaise ghar ki deewarein. <strong>CSS</strong> rang bharta hai. Aur <strong>JavaScript</strong> buttons ko zinda karta hai.<br>Mano: Chalo website theek karte hain aur saatwan sitara dhoondte hain!"},finish:{title:"🌐 لیول 7 مکمل!",text:"Byte: Shabash! Web expert! Deewarein, rang aur buttons wapis aa gaye, aur ek chamakta button dabate hi saatwan sitara nikal aaya! Mano ne yeh bhi seekha ke jab page na mile to <strong>404</strong> aata hai.<br>Byte: Agle sitare ke raaste mein kuch cheezein safe hain aur kuch risky. Dhyan se chalna hoga!"}},8:{story:{title:"لیول 8: حفاظت",text:"Saat sitare mil gaye! Aaj Mano tablet par game khel rahi thi ke chat mein ek anjaan player ne likha: Hi! Tumhara ghar kahan hai? Main tumhe inaam bhejunga.<br>Mano ruk gayi.<br>Byte: Achha kiya jo jawab nahi diya. Online anjaan log dost nahi hote.<br>Mano: To phir kya karoon?<br>Byte: Foran Ammi ya Abbu ko batao. Kuch cheezein <strong>safe</strong> hain, jaise bade ki ijazat se game khelna. Kuch <strong>risky</strong> hain, jaise anjaan link ya apna pata batana.<br>Byte: Aathwan sitara tab milega jab tum safe aur risky ko alag kar do.<br>Mano: Chalo pehchanein!"},finish:{title:"🛡️ لیول 8 مکمل!",text:"Byte: Shabash! Safety hero! Mano ne apna pata nahi bataya, password kisi ko nahi diya, aur Ammi ko sab kuch bata diya. Ammi ne us player ko block kar diya. Aathwan sitara khushi se chamak utha!<br>Byte: Ab Glitch nawen sitare ke qile ka darwaza baar baar khatkhata raha hai. Chalo defend karte hain!"}},9:{story:{title:"لیول 9: دفاع",text:"Aath sitare wapis! Aaj tablet baar baar bip bip kar raha tha.<br>Byte: Dekho Mano! Glitch ne nawen sitare ke qile par 50 baar ghalat password try kiya hai.<br>Mano: Woh andar aana chahta hai!<br>Byte: Isi liye aaj hum <strong>defender</strong> banenge. Defence ke teen kaam hain: raaz mehfooz rakhna (<strong>Confidentiality</strong>), data sahi rakhna (<strong>Integrity</strong>), aur service chalu rakhna (<strong>Availability</strong>).<br>Mano: Jaise meri diary: chhupi rahe, koi us mein kuch na badle, aur zaroorat par mil jaye!<br>Byte: Bilkul! Chalo qila bachate hain."},finish:{title:"🛡️ لیول 9 مکمل!",text:"Byte: Shabash! Defender ban gayi! Mano ne pehchana ke 50 baar ghalat password khatre ki nishani hai, aur sahi steps se qila mehfooz kiya. Nawan sitara chamak utha!<br>Lekin Glitch jaate jaate kuch nishan chhor gaya hai. Byte: Agli baar hum detective ban kar saboot dhoondenge!"}},10:{story:{title:"لیول 10: ثبوت",text:"Nau sitare mil gaye! Aaj ghar mein ek puzzle tha: Mano ki rangeen pencils ka dabba ghayab tha!<br>Noori Aapi: Detective Mano, saboot dhoondo!<br>Mano ne dekha: farsh par rang ke nishan, aur Harmi ki drawing mein bilkul wahi rang! Dabba Harmi ke paas tha. Sab hans pade.<br>Byte: Wah! Aap ne andaza nahi lagaya, saboot dekha. Glitch bhi computer mein nishan chhor gaya hai. <strong>Timestamp</strong> batata hai kab hua, <strong>logs</strong> records hain, aur <strong>hash</strong> file ka nishan hai.<br>Mano: Chalo daswan sitara dhoondte hain!"},finish:{title:"🔍 لیول 10 مکمل!",text:"Byte: Shabash! Detective Mano! Mano ne saboot sahi tarteeb mein jode, aur unhi se pata chala ke Glitch ne daswan sitara kahan chhupaya tha. Sitara mil gaya!<br>Byte: Ab gyarahwan sitara ek AI robot ke paas hai, jo kabhi kabhi ulti seedhi baatein karta hai…"}},11:{story:{title:"لیول 11: AI",text:"Das sitare wapis! Aaj ek AI robot gyarahwan sitara sambhal raha tha. Mano ne usay ek billi ki tasveer dikhayi.<br>AI robot: Yeh kutta hai!<br>Mano hans padi: Nahi, yeh billi hai!<br>Byte: <strong>AI</strong> ek machine hai jo <strong>data</strong>, yaani examples, se seekhti hai. Glitch ne is ko kuch ghalat tasveerein dikha di thin, is liye yeh ulat gaya.<br>Mano: To AI hamesha sahi nahi hota?<br>Byte: Nahi! Is liye AI ka jawab hamesha check karo. Chalo isay sahi sikhate hain."},finish:{title:"🤖 لیول 11 مکمل!",text:"Byte: Shabash! AI samajh gayi! Mano ne seekha ke data examples hain, training seekhna hai, aur model seekha hua dimaag hai. AI robot ne sahi jawab diya, billi!, aur gyarahwan sitara de diya.<br>Byte: Bas ek sitara baqi hai, aur Glitch khud usay le kar baitha hai. Aakhri challenge tayyar hai!"}},12:{story:{title:"لیول 12: آخری امتحان",text:"Gyarah sitare chamak rahe the! Bas aakhri baqi tha. Aaj Glitch khud tablet par aa gaya, sitara haath mein liye.<br>Glitch: Hi hi! Yeh sitara tabhi milega jab tum mera aakhri challenge jeeto!<br>Noori Aapi aur Harmi bhi Mano ke paas aa baithe.<br>Byte: Mano, ab tak jo seekha, sab yaad karo: computer ke hisse, password, safe messages, network, code, saboot aur AI.<br>Mano: Main tayyar hoon!<br>Noori: Go Mano, go!"},finish:{title:"🏆 MANO HERO!",text:"Byte: Shabash Mano! Aap ne 12 levels mukammal kar liye! Aap ek real Cyber Hero hain! Glitch ne muskura kar aakhri sitara wapis kar diya: Tum jeet gayi, Mano! Ab main shararat nahi karunga. Byte ki Hero Shield ke saare 12 sitare jagmaga uthe, aur poore ghar ne taaliyan bajayin!"}}},harmi:{1:{story:{title:"ہارمی لیول 1 — رنگ",text:"بائٹ: ہارمی، آج گھر میں رنگوں کا میلہ ہے، مگر سارے غبارے سفید ہو گئے ہیں! آؤ، ہم مل کر رنگ ڈھونڈیں: لال، نیلا اور پیلا۔ بڑے رنگین بلبلوں کو چھو کر غباروں میں رنگ بھرو!"},finish:{title:"🌟 شاباش ہارمی!",text:"والدین: ہارمی نے رنگ سیکھ لیے! غبارے لال، نیلے اور پیلے ہو گئے۔ بائٹ: اب میلے کے لیے شکلیں چاہییں!"}},2:{story:{title:"ہارمی لیول 2 — شکلیں",text:"بائٹ: ہارمی، رنگین غبارے لگ گئے، شاباش! اب میلے کے لیے کیک بنانا ہے۔ کیک گول ہو گا، اور اوپر چھوٹی چھوٹی تکون جھنڈیاں۔ آؤ، گول اور تکون شکلیں ڈھونڈیں!"},finish:{title:"🌟 شاباش ہارمی!",text:"والدین: ہارمی نے شکلیں سیکھ لیں! گول کیک اور تکون جھنڈیاں تیار ہیں۔ بائٹ: اب میلے کے کھیل کی باری ہے!"}},3:{story:{title:"ہارمی لیول 3 — ملانا",text:"بائٹ: ہارمی، کیک تیار ہے! اب میلے میں ایک مزے کا کھیل ہے۔ سارے کارڈ الٹے پڑے ہیں۔ کارڈ پلٹو اور ایک جیسی تصویروں کا جوڑا ڈھونڈو!"},finish:{title:"🌟 شاباش ہارمی!",text:"والدین: ہارمی نے ملانا سیکھ لیا! سارے جوڑے مل گئے۔ بائٹ: اب ہم دیکھیں گے کہ کیا محفوظ ہے اور کیا نہیں۔"}},4:{story:{title:"ہارمی لیول 4 — محفوظ/خطرناک",text:"بائٹ: ہارمی، میلے میں بہت سی چیزیں ہیں۔ کچھ محفوظ ہیں، جیسے امی ابو کے ساتھ کھیلنا۔ کچھ خطرناک ہیں، جیسے کسی انجان سے چیز لینا۔ والدین ساتھ بیٹھیں، اور مل کر ہر چیز صحیح جگہ رکھیں!"},finish:{title:"🌟 شاباش ہارمی!",text:"والدین: ہارمی نے محفوظ اور خطرناک کا فرق سیکھ لیا! بائٹ: کچھ سمجھ نہ آئے تو امی ابو سے پوچھنا۔ اب جھنڈیوں کی لڑی بنانی ہے!"}},5:{story:{title:"ہارمی لیول 5 — پیٹرن",text:"بائٹ: ہارمی، تم نے محفوظ چیزیں پہچان لیں، شاباش! اب جھنڈیوں کی لڑی لگانی ہے: لال، نیلا، لال، نیلا… اگلا کون سا آئے گا؟ پیٹرن دیکھو اور اگلی چیز چنو!"},finish:{title:"🌟 شاباش ہارمی!",text:"والدین: ہارمی نے پیٹرن سیکھ لیا! جھنڈیوں کی لڑی مکمل ہو گئی۔ بائٹ: اب میلہ شروع ہونے والا ہے!"}},6:{story:{title:"ہارمی لیول 6 — آخری",text:"بائٹ: ہارمی، میلہ تیار ہے! نوری آپی، مانو آپی اور امی ابو سب آ گئے ہیں۔ آخری کھیل میں رنگ، شکلیں اور پیٹرن، سب یاد کرو۔ سب تمہارے لیے تالیاں بجانے کو تیار ہیں!"},finish:{title:"🏆 ہارمی ہیرو!",text:"بائٹ: شاباش ہارمی! تم نے سب کچھ سیکھ لیا! تم ایک لٹل ایکسپلورر ہو! سب نے تالیاں بجائیں اور رنگوں کا میلہ جگمگا اٹھا۔"}}}},e={title:"کمپیوٹر کی کہانیاں",subtitle:"نوری، مانو، ہارمی اور بائٹ کے ساتھ 12 مہم جوئی",cover:"📖",chapters:[{id:1,title:"باب 1: کمپیوٹر کے اندر — گلچ کی پہلی شرارت",content:'<p>اتوار کی شام تھی۔ نوری، مانو اور ننھی ہارمی لاؤنج میں گھر کے کمپیوٹر کے سامنے بیٹھی تھیں۔ ان کا دوست بائٹ بھی ساتھ تھا۔ بائٹ ایک چھوٹا سا نیلا روبوٹ ہے، جس کی آنکھیں دو گول بتیوں جیسی چمکتی ہیں۔</p><p>نوری کے ہاتھ میں اسکول کا ایک پرچہ تھا۔ اس نے خوشی سے پڑھا: "ڈیجیٹل میلہ! ٹھیک 12 دن بعد۔ ہر بچہ کمپیوٹر کا ایک پروجیکٹ بنائے گا۔"</p><p>"میں ایک ویب سائٹ بناؤں گی،" نوری بولی۔ "اس کا نام ہو گا: محفوظ رہو! اس میں بچوں کو انٹرنیٹ پر محفوظ رہنا سکھاؤں گی۔"<br>"میں مدد کروں گی!" مانو نے کہا۔<br>"میں بھی!" ننھی ہارمی نے تالی بجائی۔</p><p>نوری نے کمپیوٹر پر لکھنا شروع کیا: محفوظ رہو۔ مگر اسکرین پر آیا: "وہفظ مرحو"! سارے حروف الٹے پلٹے ہو گئے تھے۔ ہر تھوڑی دیر بعد کونے میں ایک چھوٹا سا شرارتی چہرہ چمکتا اور غائب ہو جاتا۔ کمپیوٹر کا پنکھا زور زور سے گھوں گھوں کر رہا تھا۔</p><p>"یہ کون ہے؟" مانو نے پوچھا۔<br>بائٹ کی بتیاں پیلی ہو گئیں۔ "یہ <strong>گلچ</strong> ہے۔ ایک شرارتی پروگرام۔ یہ چیزیں الٹ پلٹ کرتا ہے اور کمپیوٹر کو تھکا دیتا ہے۔ اگر ہم نے اسے نہ روکا تو تمہارا پروجیکٹ میلے تک نہیں بن پائے گا۔"</p><p>نوری نے مٹھی بند کی۔ "تو پھر طے ہوا۔ 12 دن میں ہم گلچ کو بھی پکڑیں گے اور پروجیکٹ بھی بنائیں گے!"</p><p>"پہلے یہ سمجھنا ہو گا کہ کمپیوٹر کے اندر کیا ہے،" بائٹ بولا۔ "تب ہی پتا چلے گا کہ گلچ کہاں چھپا ہے۔ سوچو کہ کمپیوٹر ایک ریسٹورنٹ ہے۔"</p><p>"تم کیبورڈ اور ماؤس سے جو بتاتے ہو، وہ <strong>Input</strong> ہے، جیسے گاہک کا آرڈر۔ آرڈر جاتا ہے باورچی کے پاس۔ کمپیوٹر کا باورچی <strong>CPU</strong> ہے۔ یہ بہت تیزی سے ہدایات پر عمل کرتا ہے اور حساب لگاتا ہے۔"</p><p>"باورچی کے سامنے ایک میز ہوتی ہے، جس پر وہ صرف ابھی کام والی چیزیں رکھتا ہے۔ یہ <strong>RAM</strong> ہے۔ بجلی جائے تو یہ میز خالی ہو جاتی ہے۔ پیچھے ایک بڑا اسٹور روم ہے، جہاں تمہاری تصویریں اور فائلیں سنبھال کر رکھی جاتی ہیں۔ یہ <strong>Storage</strong> ہے۔ بجلی جائے تب بھی وہاں سب محفوظ رہتا ہے۔"</p><p>"اور جو کھانا گاہک کی میز تک پہنچتا ہے؟" نوری نے پوچھا۔<br>"وہ <strong>Output</strong> ہے، یعنی اسکرین پر تصویر اور اسپیکر سے آواز۔"</p><p>نوری نے پنکھے کی آواز سنی اور سوچا۔ "پنکھا اتنے زور سے چل رہا ہے، مطلب باورچی بہت مصروف ہے۔ کوئی اس سے فالتو کام کروا رہا ہے!"</p><p>وہ ابو کو بلا لائی۔ ابو نے <strong>Task Manager</strong> کھولا۔ یہ ایک فہرست ہے جو بتاتی ہے کہ کون سا پروگرام CPU کو کتنا مصروف رکھ رہا ہے۔ سب سے اوپر ایک عجیب نام تھا: <em>glitchy.exe</em>۔ یہ اکیلا CPU کا آدھا وقت کھا رہا تھا!</p><p>ابو نے اسے بند کر دیا۔ پنکھا دھیما ہو گیا اور حروف سیدھے ہو گئے۔ اسکرین پر صاف لکھا آیا: محفوظ رہو۔<br>ہارمی نے خوش ہو کر کہا: "باورچی کو آرام مل گیا!" سب ہنس پڑے۔</p><p>مگر رات کو، جب سب سونے جا رہے تھے، اسکرین کے کونے میں چند ہندسے چمکے: <em>0001 0010 0011</em>۔ ساتھ ہی گلچ کی ننھی سی ہنسی سنائی دی۔ ان ہندسوں کا کیا مطلب تھا؟</p><p><strong>آج کا سبق:</strong> کمپیوٹر Input لیتا ہے، CPU اس پر کام کرتا ہے، RAM کام کی میز ہے، Storage چیزیں سنبھالتی ہے، اور Output ہمیں نتیجہ دکھاتا ہے۔</p>',refs:[],quiz:[{q:"کمپیوٹر کا باورچی، جو ہدایات پر کام کرتا ہے، کون ہے؟",options:["RAM","CPU","اسپیکر"],correct:1,feedback:"شاباش! CPU ہدایات پر عمل کرتا اور حساب لگاتا ہے۔"},{q:"بجلی جانے کے بعد بھی تصویریں کہاں محفوظ رہتی ہیں؟",options:["Storage میں","RAM میں","ماؤس میں"],correct:0,feedback:"بالکل! Storage اسٹور روم کی طرح چیزیں سنبھال کر رکھتی ہے۔"},{q:"کمپیوٹر عجیب حرکت کرے تو نوری نے کیا کیا؟",options:["کمپیوٹر کو مارا","خود سب کچھ ڈیلیٹ کر دیا","ابو کو بلایا"],correct:2,feedback:"شاباش! مسئلہ ہو تو کسی بڑے کو بتاؤ۔"}]},{id:2,title:"باب 2: خفیہ ہندسے — بائنری اور مضبوط پاس ورڈ",content:'<p>میلے میں 11 دن باقی تھے۔ صبح ناشتے کی میز پر نوری نے کاغذ پر وہی ہندسے لکھے جو رات اسکرین پر چمکے تھے: 0001 0010 0011۔</p><p>"یہ تو صرف صفر اور ایک ہیں،" مانو نے پراٹھا کھاتے ہوئے کہا۔<br>"یہی تو کمپیوٹر کی زبان ہے،" بائٹ بولا۔ "اسے <strong>بائنری</strong> کہتے ہیں۔ کمپیوٹر کے اندر کروڑوں ننھے ننھے سوئچ ہیں۔ سوئچ آن ہو تو 1، آف ہو تو 0۔"</p><p>ہارمی بھاگ کر گئی اور کمرے کی بتی کا سوئچ دبایا۔ "آن! ایک!" پھر دوبارہ دبایا۔ "آف! صفر!"<br>"بالکل ٹھیک، ہارمی!" بائٹ کی بتیاں ہری ہو گئیں۔</p><p>بائٹ نے کاغذ پر چار خانے بنائے اور ان کے اوپر لکھا: 8، 4، 2، 1۔ "ہر خانے کی ایک قیمت ہے۔ جس خانے کے نیچے 1 ہو، اس کی قیمت جمع کر لو۔ جہاں 0 ہو، اسے چھوڑ دو۔"</p><p>نوری نے پہلا گروپ دیکھا: 0001۔ "صرف آخری خانے میں 1 ہے۔ یعنی 1۔"<br>مانو نے دوسرا لیا: 0010۔ "یہاں 2 والے خانے میں 1 ہے۔ یعنی 2!"<br>نوری نے تیسرا حل کیا: 0011۔ "2 اور 1، دونوں۔ یعنی 3۔"</p><p>"1، 2، 3..." نوری کا منہ کھلا رہ گیا۔ "میرا پاس ورڈ ہے <em>noori123</em>! گلچ کہہ رہا ہے کہ میرا پاس ورڈ بہت آسان ہے، وہ اسے سوچ سکتا ہے!"</p><p>امی چائے لے کر آئیں تو نوری نے ساری بات بتائی۔ امی نے کہا: "اچھا کیا کہ فوراً بتایا۔ چلو، مل کر نیا پاس ورڈ بناتے ہیں۔"</p><p>بائٹ نے مضبوط پاس ورڈ کے تین راز بتائے: "ایک، <strong>لمبا</strong> ہو۔ دو، <strong>انوکھا</strong> ہو، اس میں تمہارا نام یا سالگرہ نہ ہو۔ تین، ہر اکاؤنٹ کا <strong>الگ</strong> ہو، جیسے ہر دروازے کی الگ چابی۔"</p><p>"ایک مزے کی ترکیب ہے،" امی نے کہا۔ "تین چار بے جوڑ لفظ جوڑ لو، جیسے <em>Neela-Aam-Baarish-42!</em> یعنی نیلا آم اور بارش! یاد رکھنا آسان، اندازہ لگانا مشکل۔" پھر انہوں نے کہا: "یہ تو صرف مثال ہے۔ اپنا اصلی پاس ورڈ کبھی کسی کو مت دکھانا۔"</p><p>مانو نے سر کھجایا۔ "کل علی نے میرے گیم کا پاس ورڈ مانگا تھا۔ وہ تو میرا دوست ہے۔"<br>"دوست اچھا ہے، مگر پاس ورڈ دانت کے برش جیسا ہے،" امی مسکرائیں۔ "کسی سے شیئر نہیں کرتے۔ صرف امی ابو کو پتا ہو۔"</p><p>پھر امی نے اکاؤنٹ میں <strong>دو قدم والی حفاظت</strong> بھی آن کی، جسے MFA کہتے ہیں۔ اب لاگ اِن کرتے وقت امی کے فون پر ایک خفیہ کوڈ آتا ہے، جسے <strong>OTP</strong> کہتے ہیں۔ بائٹ نے سمجھایا: "یہ دوسری چابی ہے۔ اگر کوئی پاس ورڈ جان بھی لے، تب بھی OTP کے بغیر اندر نہیں آ سکتا۔ اور OTP کبھی کسی کو نہیں بتاتے، چاہے وہ کہے کہ وہ اسکول یا بینک سے ہے۔"</p><p>شام کو اسکرین پر گلچ کا چہرہ پھر چمکا، مگر اس بار وہ منہ بنا رہا تھا۔ ساتھ لکھا تھا: "اوہو! یہ تالا تو بہت مضبوط ہے!" اور وہ غائب ہو گیا۔</p><p>نوری مسکرائی۔ مگر اگلی صبح امی کا فون عجیب پیغاموں سے بھرا ہوا تھا۔</p><p><strong>آج کا سبق:</strong> کمپیوٹر 0 اور 1 کی زبان سمجھتا ہے۔ پاس ورڈ لمبا، انوکھا اور ہر جگہ الگ رکھو، کسی کو مت بتاؤ، اور OTP کبھی شیئر نہ کرو۔</p>',refs:[],quiz:[{q:"بائنری میں 0010 کتنا ہوتا ہے؟",options:["1","2","10"],correct:1,feedback:"شاباش! صرف 2 والے خانے میں 1 ہے۔"},{q:"ان میں سب سے مضبوط پاس ورڈ کون سا ہے؟",options:["noori123","Password","Neela-Aam-Baarish-42!"],correct:2,feedback:"بالکل! لمبا اور انوکھا پاس ورڈ مضبوط ہوتا ہے۔"},{q:"اگر کوئی تم سے OTP مانگے تو؟",options:["کبھی نہ بتاؤ اور بڑوں کو بتاؤ","فوراً بتا دو","صرف دوست کو بتا دو"],correct:0,feedback:"شاباش! OTP کبھی کسی کو نہیں دیتے۔"}]},{id:3,title:"باب 3: جعلی پیغامات — جاسوس نوری کا کیس",content:'<p>میلے میں 10 دن باقی تھے۔ امی کا فون میز پر بار بار بج رہا تھا۔ مانو اسی فون پر گیم کھیل رہی تھی کہ اچانک ایک رنگ برنگا پیغام کھلا:</p><p><em>"مبارک ہو! آپ نے نیا ٹیبلٹ جیت لیا! صرف 5 منٹ باقی! جلدی یہاں کلک کریں!"</em></p><p>مانو کی آنکھیں چمک اٹھیں۔ اس کی انگلی بٹن کی طرف بڑھی۔<br>"رکو، مانو!" بائٹ نے نرمی سے کہا۔ "پہلے ایک سوال۔ کیا تم نے کسی مقابلے میں حصہ لیا تھا؟"<br>"نہیں تو۔"<br>"تو پھر انعام کیسا؟"<br>مانو نے انگلی پیچھے کر لی۔ "اوہ... یہ دھوکہ ہے؟"</p><p>نوری نے ہارمی کا کھلونا محدب شیشہ اٹھایا اور اپنی آنکھ پر لگایا۔ "جاسوس نوری حاضر ہے! چلو، باقی پیغام بھی دیکھتے ہیں۔"</p><p>دوسرا پیغام تھا: <em>"میلے کی رجسٹریشن آج بند ہو رہی ہے! نیچے لنک پر جا کر اپنا پاس ورڈ اور OTP لکھیں: schoool-mela-prize.xyz"</em></p><p>نوری نے شیشے سے غور سے دیکھا۔ "اسکول کے نام میں تین o ہیں! اور ہمارا اسکول کبھی پاس ورڈ یا OTP نہیں مانگتا۔ یہ <strong>جعلی لنک</strong> ہے۔"</p><p>تیسرا پیغام امی کی سہیلی کی بیٹی سارہ کے نمبر سے تھا: <em>"ہیلو، میں مشکل میں ہوں، جلدی اپنا OTP بھیجو، کسی کو مت بتانا!"</em><br>نوری نے سر ہلایا۔ "سارہ آپی تو ہمیشہ بہت پیار سے اور صاف لکھتی ہیں۔ اور کوئی اچھا انسان OTP نہیں مانگتا۔ لگتا ہے کسی نے ان کا اکاؤنٹ چرا لیا ہے۔"</p><p>بائٹ نے تینوں پیغام ساتھ ساتھ رکھے۔ "دیکھو، دھوکے باز پیغاموں کی تین چالیں ہوتی ہیں۔ <strong>جلدی</strong>، تاکہ تم سوچو نہیں۔ <strong>لالچ</strong>، جیسے انعام۔ اور <strong>ڈر</strong>، جیسے کچھ بند ہو جائے گا یا کوئی مشکل میں ہے۔ جب یہ تینوں نظر آئیں تو رک جاؤ۔"</p><p>"تو ہم کیا کریں؟" مانو نے پوچھا۔<br>"کلک نہیں کرنا، جواب نہیں دینا، آگے کسی کو نہیں بھیجنا،" نوری نے انگلیوں پر گنا۔ "اور بڑوں کو دکھانا۔"</p><p>وہ فون لے کر امی کے پاس گئیں۔ امی نے لنک پر کلک کرنے کے بجائے اسکول کی ٹیچر مس ثنا کو ان کے اپنے نمبر پر خود فون کیا۔ مس ثنا ہنسیں: "نوری کی رجسٹریشن تو کب کی ہو چکی ہے۔ ہم کبھی ایسے لنک نہیں بھیجتے۔"</p><p>پھر امی نے سارہ کی امی کو فون کیا۔ پتا چلا کہ سارہ کا اکاؤنٹ واقعی کسی نے کھول لیا تھا۔ سارہ نے فوراً پاس ورڈ بدلا اور سب کا شکریہ ادا کیا۔ امی نے تینوں جعلی پیغام <strong>رپورٹ</strong> کر کے ڈیلیٹ کر دیے۔</p><p>"تم سب اچھے جاسوس ہو،" امی نے کہا۔ مانو نے فخر سے سینہ پھلایا۔ "اور میں نے بٹن نہیں دبایا!"</p><p>مگر مس ثنا نے ایک بات اور کہی تھی: "نوری، اپنے پروجیکٹ کا پہلا خاکہ آج شام تک اپ لوڈ کر دینا۔" اور گھر کا انٹرنیٹ کچھوے کی طرح رینگ رہا تھا۔</p><p><strong>آج کا سبق:</strong> جلدی، لالچ یا ڈر والے پیغام پر کلک مت کرو۔ لنک غور سے دیکھو، بڑوں کو دکھاؤ، اور اصل شخص سے خود رابطہ کر کے تصدیق کرو۔</p>',refs:[],quiz:[{q:"دھوکے باز پیغام کی تین چالیں کون سی ہیں؟",options:["جلدی، لالچ اور ڈر","ہیلو، شکریہ اور بائے","رنگ، تصویر اور گانا"],correct:0,feedback:"شاباش! جلدی، لالچ اور ڈر دیکھ کر رک جاؤ۔"},{q:"مشکوک پیغام ملنے پر کیا کرنا چاہیے؟",options:["فوراً کلک کرنا","بڑوں کو دکھانا اور تصدیق کرنا","سب دوستوں کو بھیج دینا"],correct:1,feedback:"بالکل! یہی محفوظ طریقہ ہے۔"}]},{id:4,title:"باب 4: نیٹ ورک کی سڑکیں — گمشدہ پیکٹ",content:'<p>میلے میں 9 دن باقی تھے، اور آج شام تک پروجیکٹ کا خاکہ اپ لوڈ کرنا تھا۔ نوری نے بٹن دبایا۔ اسکرین پر لکھا آیا: <em>اپ لوڈ ہو رہا ہے... 37%</em>۔ پھر سوئی وہیں اٹک گئی۔</p><p>"اف! انٹرنیٹ کو کیا ہوا؟" نوری نے ماتھے پر ہاتھ رکھا۔<br>بائٹ قریب آیا۔ "پہلے دیکھتے ہیں کہ فائل سفر کیسے کرتی ہے۔ ہارمی، ذرا اپنے کھیل والے لفافے لے آؤ!"</p><p>ہارمی دوڑ کر رنگین لفافوں کا ڈھیر لے آئی۔ بائٹ نے نوری کی ایک تصویر کے چھوٹے چھوٹے ٹکڑے کیے اور ہر ٹکڑا الگ لفافے میں ڈالا۔ "انٹرنیٹ پر بڑی فائل ایک ساتھ نہیں جاتی۔ وہ چھوٹے چھوٹے حصوں میں جاتی ہے، جنہیں <strong>پیکٹ</strong> کہتے ہیں۔"</p><p>"ہر لفافے پر پتا لکھا ہوتا ہے، جیسے گھر کا پتا۔ کمپیوٹر کے پتے کو <strong>IP address</strong> کہتے ہیں۔ یہ نمبروں کا بنا ہوتا ہے۔"</p><p>"مگر ہم تو اسکول کا نام لکھتے ہیں، نمبر تو نہیں،" مانو نے کہا۔<br>"شاباش، اچھا سوال!" بائٹ بولا۔ "اسی لیے <strong>DNS</strong> ہے۔ یہ فون بک کی طرح ہے۔ تم نام بتاتے ہو، یہ اس کا نمبر والا پتا ڈھونڈ کر دیتا ہے۔"</p><p>"اور یہ لفافے جاتے کہاں سے ہیں؟"<br>بائٹ نے کونے میں رکھے چھوٹے سے ڈبے کی طرف اشارہ کیا جس پر ہری بتیاں جل رہی تھیں۔ "یہ <strong>Router</strong> ہے، گھر کا ڈاک خانہ۔ یہ ہر پیکٹ کا پتا دیکھ کر اسے صحیح سڑک پر بھیجتا ہے۔"</p><p>ہارمی نے ٹوپی پہنی اور لفافے بانٹنے لگی۔ "ڈاکیا آ گیا! پیکٹ لے لو!" ایک لفافہ صوفے کے نیچے گر گیا۔<br>"دیکھا؟" بائٹ نے کہا۔ "کبھی کبھی کوئی پیکٹ راستے میں کھو جاتا ہے۔"</p><p>نوری نے اسکرین پر WiFi کا نشان دیکھا اور چونک گئی۔ وہاں لکھا تھا: <em>Free_Fast_WiFi</em>۔ "یہ ہمارا WiFi نہیں ہے! ہمارا تو <em>Noori-Ghar</em> ہے۔"<br>کونے میں گلچ کا چہرہ ہنسا اور غائب ہو گیا۔ اسی نے کمپیوٹر کو انجان WiFi سے جوڑ دیا تھا!</p><p>بائٹ نے سنجیدگی سے کہا: "انجان WiFi کمزور بھی ہو سکتا ہے اور غیر محفوظ بھی۔ پتا نہیں اسے کون چلا رہا ہے۔ ایسے WiFi سے خود کبھی مت جڑو، پہلے بڑوں سے پوچھو۔"</p><p>نوری ابو کو بلا لائی۔ ابو نے کمپیوٹر کو گھر کے WiFi سے جوڑا اور انجان WiFi کو <strong>Forget</strong> کر دیا، تاکہ کمپیوٹر خود اس سے دوبارہ نہ جڑے۔</p><p>اپ لوڈ پھر چل پڑا: 60%... 85%... 100%! "مگر جو پیکٹ کھو گئے تھے، ان کا کیا ہوا؟" نوری نے پوچھا۔<br>"<strong>TCP</strong> نام کا اصول کہتا ہے: ہر پیکٹ پہنچنا چاہیے۔ جو کھو جائے، وہ دوبارہ بھیجو۔ اسی لیے تمہاری فائل پوری پہنچی،" بائٹ نے کہا۔ ہارمی نے بھی صوفے کے نیچے سے اپنا لفافہ نکال کر دوبارہ پہنچا دیا۔</p><p>رات کو سب نے نانی سے ویڈیو کال کی۔ ایک لمحے کو نانی کی تصویر دھندلی ہوئی، مگر کال رکی نہیں۔ بائٹ نے بتایا: "ویڈیو کال میں <strong>UDP</strong> چلتا ہے۔ وہ کہتا ہے: ایک دو پیکٹ کھو جائیں تو کوئی بات نہیں، بس بات چلتی رہے۔"</p><p>سب سونے لگے تو اچانک بائٹ اپنی جگہ پر گول گول گھومنے لگا، اور رکنے کا نام ہی نہیں لے رہا تھا!</p><p><strong>آج کا سبق:</strong> انٹرنیٹ پر فائلیں پیکٹ بن کر سفر کرتی ہیں، DNS نام کو پتا بناتا ہے اور Router راستہ دکھاتا ہے۔ انجان WiFi سے بڑوں سے پوچھے بغیر مت جڑو۔</p>',refs:[],quiz:[{q:"DNS کا کام کیا ہے؟",options:["نام کو IP پتے میں بدلنا","پیکٹ کو پھاڑنا","ویب سائٹ کا رنگ بدلنا"],correct:0,feedback:"شاباش! DNS فون بک کی طرح ہے۔"},{q:"انٹرنیٹ پر فائل کن حصوں میں سفر کرتی ہے؟",options:["کتابوں میں","پیکٹ میں","بوتلوں میں"],correct:1,feedback:"بالکل! فائل چھوٹے پیکٹ بن کر جاتی ہے۔"},{q:"انجان WiFi نظر آئے تو کیا کرنا چاہیے؟",options:["فوراً جڑ جانا","سب کو پاس ورڈ بتانا","پہلے بڑوں سے پوچھنا"],correct:2,feedback:"شاباش! انجان WiFi محفوظ نہیں بھی ہو سکتا۔"}]},{id:5,title:"باب 5: منطق کی لیب — بائٹ جو رک نہیں رہا تھا",content:'<p>میلے میں 8 دن باقی تھے، اور بائٹ ساری رات گھومتا رہا تھا۔ گول، گول، گول۔ "ایک اور چکر... ایک اور چکر..." وہ تھکی ہوئی آواز میں کہہ رہا تھا۔</p><p>"بائٹ! رک جاؤ!" مانو نے کہا۔<br>"رک... نہیں... سکتا..." بائٹ بولا۔ "میری ہدایات... بدل دی گئی ہیں۔"</p><p>نوری نے لیپ ٹاپ کھولا اور ابو کی مدد سے بائٹ کی ہدایات والی اسکرین دیکھی۔ وہاں رنگین بلاکس میں لکھا تھا: <em>ہمیشہ: گھومو</em>۔ اور نیچے ایک چھوٹا سا نوٹ: "گلچ تھا یہاں!"</p><p>"یہ <strong>Loop</strong> ہے،" بائٹ نے گھومتے گھومتے سمجھایا۔ "لوپ یعنی ایک کام بار بار کرنا۔ یہ بہت کام کی چیز ہے، مگر اسے پتا ہونا چاہیے کہ کب رکنا ہے۔ گلچ نے رکنے والی بات مٹا دی!"</p><p>نوری نے سوچا۔ "پہلے مجھے سمجھنا ہے کہ ہدایات کیسے کام کرتی ہیں۔" بائٹ نے کہا: "ہر پروگرام تین چیزوں سے بنتا ہے۔ پہلی ہے <strong>Sequence</strong> یعنی ترتیب۔ کام کس کے بعد کون سا ہو۔"</p><p>مانو ہنسی۔ "جیسے پہلے موزے، پھر جوتے!" اس نے الٹا کر کے دکھایا: پہلے جوتا پہنا، پھر اس کے اوپر موزہ چڑھانے لگی۔ ہارمی ہنستے ہنستے لوٹ پوٹ ہو گئی۔<br>"بالکل!" بائٹ بولا۔ "ترتیب غلط ہو تو نتیجہ بھی عجیب ہوتا ہے۔"</p><p>"دوسری چیز Loop ہے، جو تم دیکھ ہی رہی ہو۔ اور تیسری ہے <strong>Condition</strong> یعنی شرط۔ اگر ایسا ہو تو یہ کرو، ورنہ وہ کرو۔ جیسے: اگر بارش ہو تو چھتری لو، ورنہ ٹوپی پہنو۔"</p><p>نوری نے ہدایات بدلیں: <em>5 بار: گھومو</em>۔ پھر <em>رک جاؤ</em>۔ اس نے بٹن دبایا۔<br>بائٹ گھومتا رہا... اور گھومتا رہا۔ دس، بیس، تیس چکر!</p><p>"کیوں نہیں رکا؟" مانو نے پوچھا۔<br>نوری نے غور سے اسکرین دیکھی۔ "اوہ! میں نے 5 کی جگہ 50 لکھ دیا تھا!" وہ ہنس پڑی۔ "یہ میری اپنی غلطی ہے۔"</p><p>"اسے <strong>Bug</strong> کہتے ہیں،" بائٹ نے کہا۔ "اور غلطی ڈھونڈ کر ٹھیک کرنے کو <strong>Debugging</strong> کہتے ہیں۔ بڑے بڑے پروگرامر بھی روز یہی کرتے ہیں۔ غلطی ڈھونڈو، ٹھیک کرو، پھر ٹیسٹ کرو۔"</p><p>نوری نے 50 کو 5 کیا اور دوبارہ چلایا۔ بائٹ نے ٹھیک پانچ چکر لگائے اور رک گیا۔ "آہ! سکون!" اس کی بتیاں ہلکی ہلکی ٹمٹمائیں۔ "تھوڑا سا چکر آ رہا ہے، مگر میں ٹھیک ہوں۔"</p><p>پھر نوری نے ایک شرط بھی ڈالی: <em>اگر سامنے دیوار ہو تو دائیں مڑو، ورنہ آگے چلو</em>۔ اب بائٹ کمرے میں آرام سے چلنے لگا، اور دیوار آتے ہی خود مڑ جاتا۔ ہارمی اس کے پیچھے پیچھے مارچ کرنے لگی۔</p><p>نوری نے اپنی کاپی بند کی اور آنکھیں چمکائیں۔ "اگر میں بائٹ کو ہدایات دے سکتی ہوں، تو میلے کے لیے اپنا پروگرام بھی لکھ سکتی ہوں! ایک کوئز!"</p><p><strong>آج کا سبق:</strong> ہر پروگرام ترتیب (Sequence)، تکرار (Loop) اور شرط (Condition) سے بنتا ہے۔ لوپ کو رکنا آنا چاہیے، اور غلطی ڈھونڈ کر ٹھیک کرنا Debugging ہے۔</p>',refs:[],quiz:[{q:"لوپ کا کام کیا ہے؟",options:["ایک کام بار بار کرنا","کچھ بھی نہ کرنا","کمپیوٹر بند کرنا"],correct:0,feedback:"شاباش! لوپ کام دہراتا ہے، مگر اسے رکنا بھی آنا چاہیے۔"},{q:"بائٹ 50 چکر کیوں لگاتا رہا؟",options:["وہ ناراض تھا","نوری نے 5 کی جگہ 50 لکھ دیا تھا","بجلی چلی گئی تھی"],correct:1,feedback:"بالکل! یہ بگ تھا، اور اسے ڈھونڈنا Debugging ہے۔"}]},{id:6,title:"باب 6: نوری کا پہلا پروگرام — Python کا کوئز",content:'<p>میلے میں 7 دن باقی تھے۔ نوری نے لیپ ٹاپ پر <strong>Python</strong> کھولا۔ ایک سفید اسکرین پر ننھا سا کرسر ٹمٹما رہا تھا، جیسے کہہ رہا ہو: "مجھے کچھ بتاؤ!"</p><p>"پروگرام لکھنا کمپیوٹر کو صاف صاف ہدایات دینا ہے،" بائٹ نے کہا۔ "اور کمپیوٹر بالکل وہی کرتا ہے جو تم لکھو، نہ کم نہ زیادہ۔"</p><p>نوری نے اپنی پہلی لائن لکھی: <em>print("Hello, Digital Mela!")</em>۔ اس نے Run دبایا تو اسکرین پر آیا: <strong>Hello, Digital Mela!</strong><br>"اس نے میری بات مان لی!" نوری خوشی سے اچھل پڑی۔ مانو اور ہارمی نے تالیاں بجائیں۔</p><p>"<em>print</em> کمپیوٹر کو کہتا ہے کہ یہ لکھ کر دکھاؤ،" بائٹ نے بتایا۔ "اب ایک ڈبہ بناتے ہیں۔"<br>"ڈبہ؟" مانو حیران ہوئی۔</p><p>"ہاں، اسے <strong>Variable</strong> کہتے ہیں۔ یہ ایک ڈبہ ہے جس پر نام کی پرچی لگی ہو، اور اندر کوئی چیز رکھی ہو۔" نوری نے لکھا: <em>name = "Mano"</em>۔ "دیکھو، ڈبے کا نام <em>name</em> ہے، اور اندر رکھا ہے Mano۔"</p><p>پھر نوری نے اپنا کوئز بنایا۔ پروگرام پہلے نام پوچھتا، پھر عمر، پھر سوال کرتا: "کیا OTP دوست کو بتانا چاہیے؟" اگر جواب "نہیں" ہوتا تو لکھتا: "شاباش، سائبر ہیرو!"</p><p>"میں آزماؤں؟" ہارمی نے پوچھا۔ نوری نے اسے گود میں بٹھا لیا۔ جب پروگرام نے عمر پوچھی تو ہارمی نے خوشی سے کیبورڈ پر ہاتھ مارا: <em>jjjkk</em>۔</p><p>اسکرین پر لال رنگ کی لمبی لکیریں آ گئیں: <em>Error!</em> پروگرام رک گیا۔ کونے میں گلچ کا چہرہ چمکا اور ایک پرچی آئی: "ہاہا! تمہارا پروگرام تو ایک بچی نے توڑ دیا!"</p><p>ہارمی کا ہونٹ لٹک گیا۔ "میں نے توڑ دیا؟"<br>"نہیں، جان،" نوری نے اسے پیار کیا۔ "تم نے تو ہماری مدد کی ہے! تم نے ایک کمزوری دکھا دی۔"</p><p>بائٹ نے سر ہلایا۔ "اچھا پروگرام یہ سوچ کر لکھا جاتا ہے کہ لوگ کچھ بھی ٹائپ کر سکتے ہیں۔ غلطی سے، یا جلدی میں۔ اس لیے پروگرام کو پہلے <strong>جانچنا</strong> چاہیے کہ جو لکھا گیا وہ ٹھیک ہے یا نہیں۔"</p><p>نوری نے ایک شرط لکھی، بالکل ویسی جیسی کل بائٹ کے لیے لکھی تھی: <em>if age.isdigit():</em> یعنی اگر عمر صرف نمبروں میں ہو تو آگے چلو، <em>else:</em> ورنہ پیار سے کہو: "براہ مہربانی عمر نمبروں میں لکھیں، جیسے 7۔"</p><p>اب ہارمی نے پھر کیبورڈ پر ہاتھ مارا۔ اس بار نہ لال لکیریں آئیں، نہ پروگرام رکا۔ اسکرین نے نرمی سے کہا: <em>براہ مہربانی عمر نمبروں میں لکھیں، جیسے 7۔</em><br>مانو نے مدد کی اور ہارمی نے 4 دبایا۔ پروگرام نے کہا: "شاباش، سائبر ہیرو!" ہارمی خوشی سے ناچنے لگی۔</p><p>گلچ کی پرچی خاموشی سے غائب ہو گئی۔ نوری نے کہا: "اب اس کوئز کو ایک گھر چاہیے، جہاں سب اسے کھیل سکیں۔"<br>"ویب سائٹ!" مانو چلائی۔ "اس کا بٹن میں بناؤں گی!"</p><p><strong>آج کا سبق:</strong> print اسکرین پر لکھتا ہے، Variable نام والا ڈبہ ہے، اور اچھا پروگرام یہ جانچتا ہے کہ لوگوں نے جو لکھا وہ ٹھیک ہے، تاکہ وہ ٹوٹے نہیں۔</p>',refs:[],quiz:[{q:"Python میں اسکرین پر لکھنے کے لیے کیا استعمال ہوتا ہے؟",options:["print","echo","jump"],correct:0,feedback:"شاباش! print لکھ کر دکھاتا ہے۔"},{q:"Variable کس چیز جیسا ہے؟",options:["ٹوٹا ہوا کھلونا","نام کی پرچی والا ڈبہ","بند دروازہ"],correct:1,feedback:"بالکل! Variable میں ہم چیزیں رکھتے ہیں۔"},{q:"ہارمی کے غلط ٹائپ کرنے سے کیا سیکھا؟",options:["ہارمی کو ڈانٹو","کیبورڈ چھپا دو","پروگرام کو ٹائپ کی ہوئی چیز جانچنی چاہیے"],correct:2,feedback:"شاباش! اچھا پروگرام غلط بات پر بھی نہیں ٹوٹتا۔"}]},{id:7,title:"باب 7: ویب کا گھر — ٹوٹا ہوا بٹن",content:'<p>میلے میں 6 دن باقی تھے۔ ابو کی مدد سے نوری نے اپنی ویب سائٹ "محفوظ رہو" کا پہلا صفحہ بنا لیا تھا۔ مانو نے وعدے کے مطابق ایک بٹن بنایا تھا جس پر لکھا تھا: <strong>کوئز کھیلو!</strong></p><p>"سب دیکھو! میرا بٹن!" مانو نے فخر سے کلک کیا۔<br>مگر اسکرین پر کوئز کی جگہ بڑے بڑے حروف آئے: <em>404 — Page Not Found</em>۔</p><p>"گلچ نے پھر شرارت کی!" مانو نے غصے سے کہا۔<br>"شاید،" بائٹ بولا۔ "مگر کسی کو الزام دینے سے پہلے ثبوت دیکھتے ہیں۔ 404 کا مطلب ہے کہ اس پتے پر کوئی صفحہ نہیں ملا۔ جیسے کوئی خط ایسے گھر نمبر پر بھیجے جو اس گلی میں ہے ہی نہیں۔"</p><p>نوری نے بٹن کا <strong>link</strong> کھولا، یعنی وہ پتا جہاں بٹن لے کر جاتا ہے۔ وہاں لکھا تھا: <em>qiuz.html</em>۔ پھر اس نے فائلوں کی فہرست دیکھی۔ کوئز کی فائل کا نام تھا: <em>quiz.html</em>۔</p><p>"دیکھو، i اور u کی جگہ بدلی ہوئی ہے،" نوری نے کہا۔<br>مانو کا چہرہ لال ہو گیا۔ وہ تھوڑی دیر چپ رہی، پھر آہستہ سے بولی: "یہ... میں نے ٹائپ کیا تھا۔ گلچ نے نہیں۔ سوری۔"</p><p>نوری نے اس کے کندھے پر ہاتھ رکھا۔ "سچ بولنا بہت بہادری کی بات ہے، مانو۔ غلطی سب سے ہوتی ہے۔ چلو، ٹھیک کرتے ہیں۔"<br>مانو نے خود <em>qiuz</em> کو <em>quiz</em> کیا۔ اس بار کلک کیا تو کوئز کھل گیا! ہارمی نے تالیاں بجائیں۔</p><p>"اب تمہیں ویب سائٹ کا راز بتاتا ہوں،" بائٹ نے کہا۔ "ویب سائٹ ایک گھر کی طرح ہے، جو تین چیزوں سے بنتا ہے۔"</p><p>"پہلی <strong>HTML</strong> ہے، یعنی گھر کی دیواریں اور کمرے۔ کہاں عنوان ہو گا، کہاں تصویر، کہاں بٹن۔"<br>"دوسری <strong>CSS</strong> ہے، یعنی رنگ اور سجاوٹ۔ دیواروں کا رنگ، پردوں کا ڈیزائن، حروف کتنے بڑے ہوں۔"<br>"اور تیسری <strong>JavaScript</strong> ہے، جو گھر میں حرکت لاتی ہے۔ جیسے گھنٹی بجانے پر دروازہ کھلے۔"</p><p>"مجھے رنگ کرنے ہیں!" ہارمی نے کہا۔ نوری نے CSS میں اس کا پسندیدہ رنگ ڈالا، ہلکا گلابی، اور عنوان کو بڑا اور نیلا کر دیا۔ ہارمی نے اپنی بنائی ہوئی بلی کی تصویر بھی دی، جو صفحے کے کونے میں لگ گئی۔</p><p>مانو نے JavaScript سے اپنے بٹن کو جادوئی بنا دیا۔ اب جب کوئی بٹن دباتا تو ستارے چمکتے اور لکھا آتا: "خوش آمدید، سائبر ہیرو!"</p><p>آخر میں نوری نے ایک چھوٹا سا صفحہ اور بنایا: "انٹرنیٹ پر اچھے بنو"۔ اس میں لکھا تھا: کسی کا مذاق مت اڑاؤ، برا لگنے والی بات مت لکھو، اور اگر کوئی تمہیں تنگ کرے تو بڑوں کو بتاؤ۔ بائٹ نے کہا: "یہ سب سے اہم صفحہ ہے۔"</p><p>شام کو مس ثنا کا پیغام آیا: "تمام بچوں کے پروجیکٹ اسکول کی میلے والی ویب سائٹ پر لگ گئے ہیں۔ دیکھ لیں!"<br>مانو جلدی سے دیکھنے بیٹھی۔ مگر اس نے پتا غلط ٹائپ کر دیا، اور ایک ایسا صفحہ کھل گیا جو بچوں کے لیے تھا ہی نہیں۔</p><p><strong>آج کا سبق:</strong> ویب سائٹ HTML سے بنتی، CSS سے سجتی اور JavaScript سے حرکت کرتی ہے۔ 404 کا مطلب ہے صفحہ نہیں ملا۔ الزام سے پہلے ثبوت دیکھو، اور انٹرنیٹ پر مہربان رہو۔</p>',refs:[],quiz:[{q:"404 کا مطلب کیا ہے؟",options:["کامیابی","صفحہ نہیں ملا","کمپیوٹر خراب ہے"],correct:1,feedback:"بالکل! اس پتے پر صفحہ موجود نہیں تھا۔"},{q:"ویب سائٹ کو رنگ اور سجاوٹ کون دیتا ہے؟",options:["CSS","HTML","Router"],correct:0,feedback:"شاباش! CSS سجاوٹ کا کام کرتی ہے۔"},{q:"بٹن کیوں نہیں چل رہا تھا؟",options:["گلچ کی وجہ سے","بجلی نہیں تھی","لنک میں ٹائپ کی غلطی تھی"],correct:2,feedback:"بالکل! qiuz کی جگہ quiz ہونا چاہیے تھا۔"}]},{id:8,title:"باب 8: کھلا دروازہ — اسکول کی ویب سائٹ کی کمزوری",content:'<p>میلے میں 5 دن باقی تھے۔ مانو نے اسکول کی میلے والی ویب سائٹ کا پتا غلط ٹائپ کیا تھا، اور اسکرین پر ایک عجیب صفحہ کھل گیا تھا۔ اوپر لکھا تھا: <strong>صرف ججوں کے لیے — نمبر</strong>۔</p><p>نیچے سب بچوں کے پروجیکٹ کے نام تھے، ان کے آگے نمبروں کے خانے، اور ہر خانے کے ساتھ ایک بٹن: <em>Edit</em>۔ نہ کسی نے پاس ورڈ مانگا، نہ نام پوچھا۔</p><p>"واہ!" مانو بولی۔ "میں نوری آپی کو دس میں سے دس دے دوں؟"<br>"رکو!" نوری اور بائٹ ایک ساتھ بولے۔ "کچھ بھی مت چھونا،" نوری نے کہا۔ "یہ ہمارا صفحہ نہیں ہے۔ اسے بدلنا غلط بھی ہے اور بے ایمانی بھی۔"</p><p>مانو نے جلدی سے ہاتھ ماؤس سے ہٹا لیا۔ "سوری۔ مگر یہ صفحہ کھلا کیوں ہے؟"</p><p>"اسے <strong>Vulnerability</strong> کہتے ہیں، یعنی کمزوری،" بائٹ نے سمجھایا۔ "سوچو اسکول کا اسٹاف روم ہے۔ دروازے پر لکھا ہے: صرف ٹیچرز کے لیے۔ مگر نہ تالا ہے، نہ کوئی پوچھنے والا۔ جو بھی دروازہ دھکیلے، اندر چلا جائے۔"</p><p>"مگر اس صفحے کا لنک تو کہیں نظر نہیں آتا تھا،" نوری نے کہا۔ "شاید انہوں نے سوچا کہ چھپا دینا کافی ہے۔"<br>"یہی تو غلطی ہے،" بائٹ بولا۔ "چھپانا تالا نہیں ہوتا۔ مانو نے غلطی سے پتا لکھا اور اندر پہنچ گئی۔"</p><p>"تو ٹھیک کیسے ہو گا؟" مانو نے پوچھا۔<br>"اسے <strong>Access Control</strong> کہتے ہیں،" بائٹ نے کہا۔ "ویب سائٹ کو ہر بار، ہر شخص سے پوچھنا چاہیے: تم کون ہو؟ اور کیا تمہیں اندر آنے کی اجازت ہے؟ جیسے دروازے پر ایک چوکیدار جو ہر بار کارڈ دیکھے۔"</p><p>"تو اب ہم کیا کریں؟" مانو نے پوچھا۔<br>نوری نے سوچا۔ "ہمیں خود کچھ ٹھیک نہیں کرنا۔ یہ اسکول کا کام ہے۔ ہمیں بس بڑوں کو بتانا ہے۔"</p><p>نوری نے ایک <strong>اسکرین شاٹ</strong> لیا، صفحہ بند کیا اور امی کو بلایا۔ امی نے مس ثنا کو ای میل لکھی: "ہمارے بچوں کو غلطی سے یہ صفحہ کھلا ملا۔ انہوں نے کچھ نہیں بدلا۔ تصویر ساتھ ہے۔"</p><p>اگلے دن اسکول میں کمپیوٹر کے استاد سر کامران نے نوری اور مانو کو بلایا۔ "تم نے بالکل صحیح کیا۔ تم نے کچھ چھیڑا نہیں، فوراً بتایا۔ ہم نے رات کو ہی اسے ٹھیک کر دیا ہے۔"</p><p>"کیا ہم دیکھ سکتے ہیں کہ ٹھیک ہوا یا نہیں؟" نوری نے پوچھا۔<br>سر کامران مسکرائے۔ "بہت اچھا سوال! ٹھیک کرنے کے بعد دوبارہ جانچنا ضروری ہے۔ اسے <strong>Retest</strong> کہتے ہیں۔ میری اجازت سے، میرے سامنے آزماؤ۔"</p><p>مانو نے وہی پتا لکھا۔ اس بار صفحے نے کہا: <em>براہ مہربانی ٹیچر لاگ اِن کریں۔ آپ کو اجازت نہیں ہے۔</em><br>"تالا لگ گیا!" مانو خوشی سے بولی۔ سر کامران نے دونوں کو "ننھے محافظ" کا بیج دیا۔</p><p>رات کو سب خوش خوش سوئے۔ مگر صبح ابو کا فون عجیب سے الرٹس سے بھرا ہوا تھا۔</p><p><strong>آج کا سبق:</strong> کمزوری چھپانے سے نہیں، ٹھیک کرنے سے ختم ہوتی ہے۔ ہر بار اجازت چیک ہونی چاہیے۔ کمزوری ملے تو کچھ مت چھیڑو، بڑوں کو بتاؤ، اور ٹھیک ہونے کے بعد دوبارہ جانچو۔</p>',refs:[],quiz:[{q:"کمزوری کا اصل حل کیا ہے؟",options:["لنک چھپا دینا","ہر بار اجازت چیک کرنا","رنگ بدل دینا"],correct:1,feedback:"شاباش! چھپانا تالا نہیں ہوتا، اجازت چیک کرنا تالا ہے۔"},{q:"کھلا صفحہ ملنے پر نوری نے کیا کیا؟",options:["نمبر بدل دیے","دوستوں کو لنک بھیج دیا","کچھ نہیں چھیڑا اور بڑوں کو بتایا"],correct:2,feedback:"بالکل! یہی ایک اچھے سائبر ہیرو کا طریقہ ہے۔"}]},{id:9,title:"باب 9: سائبر ڈیفنس — رات کے الرٹس",content:'<p>میلے میں 4 دن باقی تھے۔ ناشتے پر ابو نے اپنا فون میز پر رکھا۔ "دیکھو بچو، رات کو ہمارے Router کی ایپ نے یہ الرٹس بھیجے ہیں۔"</p><p>اسکرین پر لکھا تھا: <em>رات 3:40 — Router کی سیٹنگز میں لاگ اِن کی 50 ناکام کوششیں، صرف 2 منٹ میں۔ حفاظت کے لیے لاگ اِن 1 گھنٹے کے لیے بند کر دیا گیا۔</em></p><p>"پچاس بار؟" مانو نے آنکھیں پھاڑیں۔ "کوئی اتنی جلدی کیسے ٹائپ کر سکتا ہے؟"<br>"کوئی انسان نہیں کر سکتا،" بائٹ نے کہا۔ "یہ ایک پروگرام تھا جو ایک کے بعد ایک پاس ورڈ آزما رہا تھا۔ اسے <strong>Brute Force</strong> کہتے ہیں۔ جیسے کسی کے پاس چابیوں کا بڑا گچھا ہو اور وہ ہر چابی تالے میں لگا کر دیکھے۔"</p><p>"تو کیا وہ اندر آ گیا؟" نوری نے پوچھا۔<br>ابو مسکرائے۔ "نہیں۔ ہمارا پاس ورڈ لمبا اور مضبوط ہے، جیسا ہم نے اس دن مل کر سیکھا تھا۔ اور Router نے بہت سی غلط کوششیں دیکھ کر خود ہی دروازہ بند کر دیا۔"</p><p>"اب ہم کیا کریں؟" مانو نے پوچھا۔ "سب کچھ ڈیلیٹ کر دیں؟"<br>"نہیں!" بائٹ بولا۔ "گھبرانا نہیں، اور کچھ مٹانا بھی نہیں۔ ایک سائبر محافظ قدم بہ قدم چلتا ہے۔"</p><p>"پہلا قدم: <strong>ثبوت محفوظ کرو</strong>۔" نوری نے الرٹس کا اسکرین شاٹ لیا اور کاپی میں وقت لکھا: رات 3:40۔</p><p>"دوسرا قدم: پتا کرو کہ کوشش <strong>کہاں سے</strong> آئی۔" ابو نے ایپ میں دیکھا۔ وہاں ایک IP address لکھا تھا: <em>192.168.1.23</em>۔<br>بائٹ نے کہا: "یہ نمبر ہمارے گھر کے اندر والے نیٹ ورک کا ہے! یعنی کوشش باہر سے نہیں، گھر ہی کے کسی آلے سے ہوئی۔"</p><p>ابو نے Router سے جڑے آلوں کی فہرست کھولی۔ ابو کا فون، امی کا فون، لیپ ٹاپ، ٹی وی... اور ایک نام جو کوئی نہیں پہچانا: <em>Old-Tablet</em>۔</p><p>"میرا کارٹون والا ٹیبلٹ!" ہارمی نے کہا۔ "وہ اسٹور کی دراز میں ہے، چارجر پر۔"<br>سب ایک دوسرے کو دیکھنے لگے۔ پرانا ٹیبلٹ مہینوں سے دراز میں پڑا تھا، مگر چارجر لگا ہونے کی وجہ سے آن تھا اور WiFi سے جڑا ہوا تھا۔</p><p>"تیسرا قدم: اسے <strong>الگ کرو</strong>،" بائٹ نے کہا۔ ابو نے Router کی ایپ میں اس ٹیبلٹ کو بلاک کیا، پھر دراز سے ٹیبلٹ نکال کر اس کا WiFi بند کیا اور اسے الماری کے اوپر رکھ دیا۔ "اب یہ کسی سے بات نہیں کر سکتا۔"</p><p>"چوتھا قدم: احتیاطاً <strong>پاس ورڈ بدلو</strong>۔" ابو نے Router کا پاس ورڈ بدل دیا۔<br>"اور پانچواں: <strong>رپورٹ لکھو</strong>۔" نوری نے اپنی کاپی میں لکھا: کیا ہوا، کب ہوا، کہاں سے ہوا، اور ہم نے کیا کیا۔</p><p>بائٹ کی بتیاں ہری ہو گئیں۔ "نوری، تم نے ابھی بالکل ایک سائبر ڈیفنس سینٹر کے محافظ کی طرح کام کیا۔ وہ بھی یہی کرتے ہیں: دیکھو، بچاؤ، الگ کرو، ٹھیک کرو، اور لکھو۔"</p><p>نوری خوش تھی۔ مگر جب اس نے اپنی میلے والی فائل کھولی تو وہ رک گئی۔ کوئز کے کچھ جواب بدلے ہوئے تھے۔ کس نے بدلے؟</p><p><strong>آج کا سبق:</strong> عجیب الرٹ آئے تو گھبراؤ مت اور کچھ مت مٹاؤ۔ پہلے ثبوت محفوظ کرو، پھر دیکھو کہاں سے آیا، اسے الگ کرو، پاس ورڈ بدلو، اور رپورٹ لکھو۔</p>',refs:[],quiz:[{q:"مشکوک لاگ اِن ملنے پر پہلا قدم کیا ہے؟",options:["سب کچھ مٹا دینا","ثبوت محفوظ کرنا","سب کو بتا دینا کہ ہیک ہو گیا"],correct:1,feedback:"بالکل! پہلے ثبوت محفوظ کرو۔"},{q:"Brute Force کس جیسا ہے؟",options:["چابیوں کے گچھے سے ہر چابی آزمانا","دروازے پر گھنٹی بجانا","خط لکھنا"],correct:0,feedback:"شاباش! پروگرام ایک کے بعد ایک پاس ورڈ آزماتا ہے۔"},{q:"کوشش کہاں سے آئی تھی؟",options:["چاند سے","اسکول سے","گھر کے پرانے ٹیبلٹ سے"],correct:2,feedback:"بالکل! IP address گھر کے اندر والے نیٹ ورک کا تھا۔"}]},{id:10,title:"باب 10: ڈیجیٹل جاسوسی — بدلی ہوئی فائل",content:'<p>میلے میں 3 دن باقی تھے۔ نوری کی میلے والی فائل کا سائز کل تک 2 MB تھا۔ آج 3 MB تھا۔ اور کوئز کا ایک سوال بدلا ہوا تھا: "کیا OTP دوست کو بتانا چاہیے؟" کا صحیح جواب اب "ہاں" لکھا تھا!</p><p>"یہ تو بالکل غلط ہے!" نوری پریشان ہو گئی۔ "میلے میں سب بچے یہی غلط بات سیکھیں گے!"<br>"گھبراؤ مت،" بائٹ نے کہا۔ "آج ہم <strong>ڈیجیٹل فارنزکس</strong> کریں گے، یعنی کمپیوٹر کی جاسوسی۔ ہم سراغ ڈھونڈیں گے کہ کیا ہوا۔"</p><p>"پہلا اصول: اصل فائل کو مت چھیڑو۔" بائٹ نے کہا۔ "اس کی ایک <strong>کاپی</strong> بناؤ اور کاپی پر کام کرو۔ جیسے پولیس جائے واردات پر چیزیں نہیں ہلاتی، تاکہ سراغ خراب نہ ہوں۔"<br>نوری نے فائل کی کاپی بنائی اور اصل کو ایک الگ فولڈر میں رکھ دیا۔</p><p>"دوسرا سراغ: <strong>ہیش</strong>۔" بائٹ نے ایک بٹن دبایا اور اسکرین پر حروف اور نمبروں کی ایک لمبی لائن آئی۔ "یہ فائل کا فنگر پرنٹ ہے۔ اگر فائل میں ایک حرف بھی بدلے، تو یہ فنگر پرنٹ پورا بدل جاتا ہے۔"</p><p>نوری کے پاس جمعے والا بیک اپ بھی تھا۔ اس کا ہیش نکالا تو بالکل مختلف تھا۔ "یعنی پکا ثبوت ہے کہ فائل جمعے کے بعد بدلی ہے۔"</p><p>"تیسرا سراغ: <strong>وقت</strong>۔" ہر فائل یاد رکھتی ہے کہ اسے آخری بار کب بدلا گیا۔ نوری نے دیکھا: <em>رات 3:42</em>۔<br>"یہ تو الرٹس کے بالکل دو منٹ بعد کا وقت ہے!" مانو بولی۔</p><p>پھر نوری نے کمپیوٹر کے <strong>لاگ</strong> دیکھے، یعنی وہ ڈائری جس میں کمپیوٹر سب کچھ لکھتا ہے۔ اس نے ایک <strong>ٹائم لائن</strong> بنائی:<br>3:42:10 — مانو کے اکاؤنٹ سے لاگ اِن<br>3:42:15 — نوری کی فائل بدلی گئی<br>3:42:20 — لاگ آؤٹ</p><p>سب نے مانو کی طرف دیکھا۔ مانو کی آنکھوں میں آنسو آ گئے۔ "میں نے کچھ نہیں کیا! میں تو سو رہی تھی!"</p><p>بائٹ نے نرمی سے کہا: "کسی پر الزام لگانے سے پہلے ایک بات یاد رکھو۔ <strong>ثبوت الزام نہیں ہوتا</strong>۔ لاگ یہ بتاتا ہے کہ مانو کا <em>اکاؤنٹ</em> استعمال ہوا۔ یہ نہیں بتاتا کہ مانو کے <em>ہاتھوں</em> نے یہ کیا۔ ہم صرف وہی لکھیں گے جو ثابت ہے۔"</p><p>نوری نے لاگ میں ایک لائن اور پڑھی۔ لاگ اِن کس آلے سے ہوا تھا؟ وہاں لکھا تھا: <em>Old-Tablet</em>۔</p><p>مانو نے ماتھے پر ہاتھ مارا۔ "یاد آیا! بہت پہلے میں نے اس ٹیبلٹ پر اپنا اکاؤنٹ کھولا تھا، اور پاس ورڈ وہیں محفوظ رہ گیا تھا!"<br>"یعنی ٹیبلٹ میں چھپے گلچ نے تمہارا محفوظ پاس ورڈ استعمال کیا،" بائٹ نے کہا۔</p><p>نوری نے مانو کو گلے لگایا۔ "سوری، مانو۔ مجھے تم پر شک نہیں کرنا چاہیے تھا۔"<br>"کوئی بات نہیں،" مانو مسکرائی۔ "اب میں کبھی کسی پرانے آلے پر لاگ اِن چھوڑ کر نہیں جاؤں گی۔" ابو نے مانو کے اکاؤنٹ کا پاس ورڈ بدل دیا اور سب پرانے آلوں سے اسے لاگ آؤٹ کر دیا۔</p><p>نوری نے جمعے والے بیک اپ سے صحیح فائل واپس لگائی اور کوئز کا جواب پھر "نہیں" ہو گیا۔ اب صرف پوسٹر باقی تھا، اور نوری نے سوچا کہ اس کے لیے AI سے مدد لی جائے۔</p><p><strong>آج کا سبق:</strong> سراغ ڈھونڈتے وقت اصل فائل محفوظ رکھو اور کاپی پر کام کرو۔ ہیش، وقت اور لاگ سے ٹائم لائن بناؤ، اور یاد رکھو کہ ثبوت الزام نہیں ہوتا۔</p>',refs:[],quiz:[{q:"فارنزکس میں اصل فائل کے ساتھ کیا کرنا چاہیے؟",options:["اس پر کام کرنا","اسے ڈیلیٹ کرنا","اسے محفوظ رکھ کر کاپی پر کام کرنا"],correct:2,feedback:"شاباش! اصل سراغ محفوظ رہنے چاہئیں۔"},{q:"ہیش کس چیز جیسا ہے؟",options:["فائل کا فنگر پرنٹ","فائل کا رنگ","فائل کی آواز"],correct:0,feedback:"بالکل! ایک حرف بدلے تو ہیش پورا بدل جاتا ہے۔"},{q:"لاگ میں مانو کا اکاؤنٹ تھا، تو کیا مانو قصوروار تھی؟",options:["ہاں، پکا","نہیں، پہلے پورے ثبوت دیکھنے تھے","پتا نہیں، اسے ڈانٹ دو"],correct:1,feedback:"شاباش! ثبوت الزام نہیں ہوتا۔"}]},{id:11,title:"باب 11: AI کی دنیا — جب روبوٹ یقین سے غلط کہے",content:'<p>میلے میں 2 دن باقی تھے۔ نوری کو اپنے پروجیکٹ کے لیے ایک پوسٹر بنانا تھا، جس پر کمپیوٹر کے بارے میں مزے کی باتیں لکھی ہوں۔ امی کی اجازت سے اس نے ایک <strong>AI</strong> مددگار ایپ کھولی۔</p><p>نوری نے لکھا: "کمپیوٹر کا باورچی، یعنی ہدایات پر کام کرنے والا حصہ، کون سا ہے؟"<br>AI نے فوراً بڑے یقین سے جواب دیا: <em>"کمپیوٹر کا یہ حصہ RAM ہے۔ اور RAM بجلی جانے کے بعد بھی سب کچھ یاد رکھتی ہے۔"</em></p><p>"یہ تو غلط ہے!" مانو چلائی۔ "باورچی تو CPU ہے! اور RAM والی میز تو بجلی جاتے ہی خالی ہو جاتی ہے!"<br>نوری حیران تھی۔ "مگر یہ اتنے یقین سے کیسے کہہ رہا ہے؟"</p><p>بائٹ نے کہا: "AI جادو نہیں ہے۔ اس نے بہت سی لکھی ہوئی باتیں پڑھ کر سیکھا ہے کہ کون سا لفظ کس لفظ کے بعد آتا ہے۔ یہ اکثر بہت اچھے جواب دیتا ہے، مگر کبھی کبھی اپنی طرف سے ایسی بات جوڑ دیتا ہے جو سچ نہیں ہوتی، اور پھر بھی بڑے یقین سے بولتا ہے۔ اسے <strong>Hallucination</strong> کہتے ہیں۔"</p><p>"تو ہم AI پر بھروسہ نہ کریں؟" مانو نے پوچھا۔<br>"AI سے مدد لو، مگر ہر ضروری بات کی <strong>تصدیق</strong> کرو،" بائٹ بولا۔ "کتاب سے، ٹیچر سے، یا کسی بھروسے والی جگہ سے۔"</p><p>نوری نے اپنی کمپیوٹر کی کتاب کھولی۔ وہاں صاف لکھا تھا: CPU ہدایات پر عمل کرتا ہے۔ RAM عارضی یادداشت ہے۔ اس نے پوسٹر پر کتاب والی صحیح بات لکھی۔</p><p>اسی دوران ہارمی امی کے فون پر تصویریں بنانے والی AI سے کھیل رہی تھی۔ اس نے امی سے لکھوایا: "ڈاکٹر کی تصویر بناؤ۔" AI نے چار تصویریں بنائیں۔ چاروں میں صرف آدمی ڈاکٹر تھے۔</p><p>ہارمی نے منہ بنایا۔ "مگر ہماری خالہ بھی تو ڈاکٹر ہیں!"<br>"شاباش، ہارمی! تم نے ایک بڑی بات پکڑی ہے،" بائٹ نے کہا۔ "اگر AI کو سکھاتے وقت زیادہ تر ایک ہی طرح کی تصویریں دکھائی جائیں، تو وہ سمجھنے لگتا ہے کہ دنیا بس ایسی ہی ہے۔ اسے <strong>Bias</strong> کہتے ہیں، یعنی ادھوری اور یک طرفہ سوچ۔"</p><p>"اس کا علاج کیا ہے؟" نوری نے پوچھا۔<br>"AI کو ہر طرح کے لوگوں اور چیزوں کی مثالیں دکھانا، اور ہم سب کا ہوشیار رہنا،" بائٹ نے کہا۔ ہارمی نے دوبارہ لکھوایا: "لیڈی ڈاکٹر اور آدمی ڈاکٹر، ساتھ ساتھ۔" اس بار تصویر میں دونوں تھے۔ ہارمی نے خوشی سے تالی بجائی۔</p><p>بائٹ نے ایک بات اور بتائی: "AI ایپ میں کبھی اپنا پاس ورڈ، گھر کا پتا، یا اسکول کی ذاتی باتیں مت لکھو۔ اور اسے ہمیشہ بڑوں کی اجازت سے استعمال کرو۔"</p><p>نوری نے پوسٹر کے نیچے بڑے حروف میں ایک لائن لکھی: <strong>"AI سے پوچھو، مگر تصدیق ضرور کرو!"</strong> اگلے دن مس ثنا نے پوسٹر دیکھا اور سارے حقائق ٹھیک بتائے۔</p><p>پوسٹر تیار تھا، کوئز تیار تھا، ویب سائٹ تیار تھی۔ مگر الماری کے اوپر رکھا پرانا ٹیبلٹ اب بھی خاموش پڑا تھا، اور اس کے اندر گلچ ابھی تک چھپا ہوا تھا۔ کل میلہ تھا!</p><p><strong>آج کا سبق:</strong> AI ڈیٹا سے سیکھتا ہے، اس لیے کبھی یقین سے غلط بات کہہ سکتا ہے یا یک طرفہ سوچ دکھا سکتا ہے۔ AI سے مدد لو، مگر ہر بات کی تصدیق کرو اور ذاتی معلومات مت لکھو۔</p>',refs:[],quiz:[{q:"AI کبھی غلط کیوں ہوتا ہے؟",options:["وہ شرارتی ہوتا ہے","اس کا ڈیٹا ادھورا یا غلط ہو سکتا ہے","وہ کبھی غلط نہیں ہوتا"],correct:1,feedback:"بالکل! AI ڈیٹا سے سیکھتا ہے۔"},{q:"AI کا جواب ملنے پر کیا کرنا چاہیے؟",options:["کتاب یا ٹیچر سے تصدیق کرنا","فوراً سب کو بتا دینا","پاس ورڈ لکھ دینا"],correct:0,feedback:"شاباش! AI سے پوچھو، مگر تصدیق کرو۔"}]},{id:12,title:"باب 12: آخری مشن — میلے کا دن",content:'<p>آخرکار میلے کا دن آ گیا! مگر اسکول جانے سے پہلے ایک کام باقی تھا۔ ابو نے الماری کے اوپر سے پرانا ٹیبلٹ اتارا۔ "آج گلچ کا قصہ ختم کرتے ہیں۔"</p><p>پہلے ابو نے ٹیبلٹ میں موجود ہارمی کی ساری تصویریں اپنے کمپیوٹر میں محفوظ کیں، یعنی <strong>بیک اپ</strong> لیا۔ پھر نوری نے ایپس کی فہرست دیکھی۔ وہاں ایک پرانا گیم تھا: <em>Super Jumpy Fun</em>۔</p><p>"یہ تو بہت پہلے ایک انجان ویب سائٹ سے ڈاؤن لوڈ ہوا تھا،" ابو نے یاد کیا۔ بائٹ نے اس کی ہدایات دیکھیں۔ اندر وہی پرانی چیزیں تھیں: ایک لوپ جو کبھی نہیں رکتا تھا، الٹے پلٹے حروف، اور پاس ورڈ آزمانے والی ہدایات۔ یہی گلچ کا گھر تھا!</p><p>"گلچ اصل میں کوئی جادوگر نہیں تھا،" بائٹ نے کہا۔ "یہ بس ایک ایسا پروگرام تھا جسے غلط اور گندی ہدایات دی گئی تھیں، اور وہ ان پر بار بار عمل کر رہا تھا۔"</p><p>ابو نے ٹیبلٹ کو <strong>Factory Reset</strong> کیا، یعنی بالکل نئے جیسا صاف کر دیا۔ اسکرین پر آخری بار گلچ کا ننھا چہرہ چمکا، اس نے ہاتھ ہلایا: "بائے بائے!" اور ہمیشہ کے لیے غائب ہو گیا۔ پھر ابو نے ہارمی کے کارٹون صرف بھروسے والے ایپ اسٹور سے ڈالے۔ "نئی ایپ ہمیشہ بڑوں کے ساتھ، اور صرف بھروسے والی جگہ سے،" انہوں نے کہا۔</p><p>اسکول کا ہال رنگ برنگے جھنڈوں سے سجا تھا۔ نوری کی باری آئی۔ اس نے لیپ ٹاپ پروجیکٹر سے جوڑا، مگر بڑی اسکرین بالکل کالی رہی۔<br>"گلچ واپس آ گیا!" مانو نے گھبرا کر کہا۔</p><p>نوری نے گہری سانس لی۔ "رکو۔ پہلے ثبوت دیکھتے ہیں۔" لیپ ٹاپ پر سب ٹھیک چل رہا تھا۔ یعنی مسئلہ <strong>Output</strong> میں تھا، تصویر بڑی اسکرین تک نہیں پہنچ رہی تھی۔ اس نے تار دیکھا۔ وہ ڈھیلا تھا! اس نے تار ٹھیک سے لگایا اور اسکرین پر "محفوظ رہو" چمک اٹھا۔ ہال میں تالیاں بجیں۔</p><p>"ہر مسئلہ گلچ نہیں ہوتا،" نوری نے مسکرا کر مانو کے کان میں کہا۔</p><p>پھر نوری نے اپنی ویب سائٹ دکھائی اور گلچ کو پکڑنے کی پوری کہانی سنائی، بالکل ایک سائبر محافظ کی رپورٹ کی طرح: ہم نے کیا دیکھا، کیسے ثبوت بچائے، ٹیبلٹ کو کیسے الگ کیا، اسے کیسے صاف کیا، فائل کیسے واپس لائے، اور ہم نے کیا سیکھا۔</p><p>مانو نے بچوں کو کوئز کھلایا۔ بائٹ نے اپنی بتیاں جلا بجھا کر 0001 0010 0011 بنایا اور بچوں نے مل کر پڑھا: 1، 2، 3!</p><p>آخر میں مس ثنا نے اعلان کیا: "بہترین ٹیم کا انعام جاتا ہے... نوری، مانو، ہارمی اور بائٹ کو!" سر کامران نے کہا: "انہوں نے صرف مسئلہ حل نہیں کیا، بلکہ جانچ کر دکھایا کہ حل کام کرتا ہے۔"</p><p>گھر واپسی پر نوری نے کاپی میں 12 دن کے سبق لکھے: کمپیوٹر کے حصے۔ 0 اور 1 کی زبان اور مضبوط پاس ورڈ۔ جعلی پیغام کی پہچان۔ پیکٹ اور محفوظ WiFi۔ ترتیب، لوپ اور شرط۔ اپنا پروگرام۔ ویب کا گھر۔ کمزوری کی رپورٹ۔ ثبوت بچانا۔ ثبوت اور الزام کا فرق۔ AI کی تصدیق۔ اور ٹیم کے ساتھ کام۔</p><p>بائٹ کی بتیاں چمکیں۔ "مبارک ہو! اب تم سب سچے سائبر ہیرو ہو۔"<br><strong>🌟 ختم شد — اور نئی مہم جوئی جلد! 🌟</strong></p><p><strong>آج کا سبق:</strong> بڑا مسئلہ آئے تو گھبراؤ مت: ثبوت دیکھو، الگ کرو، ٹھیک کرو، جانچو، رپورٹ لکھو، اور سیکھو۔ ٹیم اور بڑوں کے ساتھ مل کر ہر مشکل حل ہو جاتی ہے۔</p>',refs:[],quiz:[{q:"بڑا سائبر مسئلہ حل کرنے کا آخری مرحلہ کیا ہے؟",options:["مسئلہ چھپا دینا","رپورٹ لکھنا اور سبق سیکھنا","کچھ نہ کرنا"],correct:1,feedback:"شاباش! رپورٹ اور سبق آخری قدم ہیں۔"},{q:"میلے میں بڑی اسکرین کالی کیوں تھی؟",options:["گلچ واپس آ گیا تھا","لیپ ٹاپ ٹوٹ گیا تھا","پروجیکٹر کا تار ڈھیلا تھا"],correct:2,feedback:"بالکل! ہر مسئلہ گلچ نہیں ہوتا، پہلے ثبوت دیکھو۔"},{q:"نئی ایپ کیسے ڈالنی چاہیے؟",options:["بڑوں کے ساتھ، بھروسے والے ایپ اسٹور سے","کسی بھی ویب سائٹ سے","دوست کے بھیجے لنک سے"],correct:0,feedback:"شاباش! گلچ انجان جگہ سے آیا تھا۔"}]}]},t={noori:"levels",mano:"manoLevels",harmi:"harmiLevels"};function r(){if(!window.app)return!1;var e=0,r=0;return Object.keys(a).forEach(function(i){var o=window.app[t[i]]||[];Object.keys(a[i]).forEach(function(t){r++;var n=o.filter(function(a){return String(a.id)===String(t)})[0];if(n&&n.steps){var h=a[i][t],s=n.steps.filter(function(a){return"story"===a.type})[0],k=n.steps.filter(function(a){return"finish"===a.type}).slice(-1)[0];h.story&&s&&(s.title=h.story.title,s.text=h.story.text),h.finish&&k&&(k.title=h.finish.title,k.text=h.finish.text),n.__storiesV4=!0,e++}})}),e===r}function i(){return!(!window.BOOKS_DATA||!window.BOOKS_DATA["computer-stories"])&&(window.BOOKS_DATA["computer-stories"].__v4||(e.__v4=!0,window.BOOKS_DATA["computer-stories"]=e),!0)}var o=0;!function e(){var t=r(),n=i();if(t&&n||++o>60)return window.StoriesV4={levels:t,book:n,data:a},void setInterval(function(){r(),i()},3e3);setTimeout(e,250)}()}();